38	/* Pre-computed ana_reg default values.  AVDK ships equivalent field-by-field
39	 * builders (aud_common_driver.c:153..291).  The hex constants below are the
40	 * comments AVDK itself left in place for reference, and match the runtime
41	 * value_cal() output field-for-field on BK7258 (SOC_BK7236XX branch).
42	 */
43	
44	#define BK7258_ANA_REG18_DEFAULT      UINT32_C(0x00BF8085)
45	#define BK7258_ANA_REG19_DEFAULT      UINT32_C(0x81800006)
46	#define BK7258_ANA_REG20_DEFAULT      UINT32_C(0xFBC02423)
47	#define BK7258_ANA_REG21_DEFAULT      UINT32_C(0x00500000)
48	#define BK7258_ANA_REG27_DEFAULT      UINT32_C(0x91800006)
49	
50	/* Analog-reg indices (0..0x2A) used by the DAC path. */
51	
52	#define BK7258_ANA_REG_APLL_PWD       5    /* pwdaudpll bit 13. */
53	#define BK7258_ANA_REG18              18
54	#define BK7258_ANA_REG19              19
55	#define BK7258_ANA_REG20              20
56	#define BK7258_ANA_REG21              21
57	#define BK7258_ANA_REG25_APLL_CFG     25
58	#define BK7258_ANA_REG26_APLL_CAL     26
59	#define BK7258_ANA_REG27              27
60	
61	/* ana_reg20 bit positions we RMW at runtime.  All widths are 1 bit unless
62	 * annotated.  Values traced from sys_ll.h.
63	 */
64	
65	#define ANA_REG20_DACDRVEN_BIT        19
66	#define ANA_REG20_DACLEN_BIT          21
67	#define ANA_REG20_DACG_BIT            22    /* 4-bit field.                */
68	#define ANA_REG20_DACG_MASK           0xFu
69	#define ANA_REG20_DACMUTE_BIT         26
70	#define ANA_REG20_DIFFEN_BIT          13
71	#define ANA_REG20_LENDCOC_BIT         16
72	
73	/* ana_reg21 bit positions. */
74	
75	#define ANA_REG21_ENIDACL_BIT         18
76	#define ANA_REG21_ENBS_BIT            23  /* sys_reg.h: SYS_ANA_REG21_ENBS_POS */
77	
78	/* ana_reg18 bit positions. */
79	
80	#define ANA_REG18_ENAUDBIAS_BIT       3
81	
82	/* ana_reg5[13] = pwdaudpll (active-high power-DOWN). */
83	
84	#define ANA_REG5_PWDAUDPLL_BIT        13
85	
86	/* ana_reg25[18] = APLL SPI trigger. */
87	
88	#define ANA_REG25_SPI_TRIGGER_BIT     18
89	
90	/* Sys ctrl (0x44010000) register offsets used at runtime. */
91	
92	/* Sys ctrl register bit positions taken from the AVDK sys_struct.h layout
93	 * for BK7258 (bk_avdk_smp/ap/middleware/soc/bk7258_ap/soc/sys_struct.h).
94	 */
95	
96	#define SYS_CLK_DIV_MODE1             (BK7258_SYS_BASE + (0x8u * 4u))
97	#define   SYS_CLK_DIV_MODE1_CKSEL_AUD_BIT   25  /* sys_struct.h:144 */
98	#define   SYS_CLK_DIV_MODE1_CKSEL_AUD_MASK  0x1u
99	
100	#define SYS_CLK_DIV_MODE2             (BK7258_SYS_BASE + (0x9u * 4u))
101	#define   SYS_CLK_DIV_MODE2_DMIC_DIV_BIT    13  /* sys_struct.h:163 */
102	
103	#define SYS_CPU_DEVICE_CLK_EN         (BK7258_SYS_BASE + (0xCu * 4u))
104	#define   SYS_CPU_DEVICE_CLK_AUD_CKEN_BIT   30  /* sys_struct.h:238 */
