106	/****************************************************************************
107	 * Private Data
108	 ****************************************************************************/
109	
110	static bool           g_bk7258_aud_subsys_ready;
111	static bool           g_bk7258_dac_configured;
112	static spinlock_t     g_bk7258_aud_lock = SP_UNLOCKED;
113	
114	/* Cached configuration so bk7258_dac_set_sample_rate() can honour the APLL
115	 * cal-value swap for the 44.1k family.
116	 */
117	
118	static bool           g_bk7258_dac_use_apll;
