120	/****************************************************************************
121	 * Private Helpers
122	 ****************************************************************************/
123	
124	/* Read-modify-write on a plain sys-ctrl register (no analog SPI).  A single
125	 * putreg32 is enough because the whole SoC AHB slave is coherent from the
126	 * CPU.  Called from init only; no interlock with IRQ paths.
127	 */
128	
129	static inline void bk7258_sys_reg_bits(uint32_t addr, uint32_t mask,
130	                                       uint32_t value)
131	{
132	  uint32_t v = getreg32(addr);
133	  v &= ~mask;
134	  v |= (value & mask);
135	  putreg32(v, addr);
136	}
137	
138	/* Analog-register write, mirrors sys_ll_set_analog_reg_value():
139	 *   REG_WRITE(addr, value);
140	 *   spin until SPI_STATE bit[idx] clears.
141	 *
142	 * The SPI transfer takes only a handful of AHB cycles; AVDK does not bound
143	 * the wait.  We keep a generous 1000-iteration cap so a stuck bus surfaces
144	 * as an error rather than a lock-up.
145	 */
146	
147	static int bk7258_ana_reg_write(uint32_t idx, uint32_t value)
148	{
149	  const uint32_t addr = BK7258_SYS_ANA_REG(idx);
150	  int loops = 1000;
151	
152	  putreg32(value, addr);
153	
154	  while ((getreg32(BK7258_SYS_ANA_SPI_STATE) & (UINT32_C(1) << idx)) != 0)
155	    {
156	      if (--loops <= 0)
157	        {
158	          auderr("BK7258: analog reg %lu SPI wait timeout\n",
159	                 (unsigned long)idx);
160	          return -ETIMEDOUT;
161	        }
162	    }
163	
164	  return OK;
165	}
166	
167	/* Read-modify-write on an analog register bit (equivalent to
168	 * sys_set_ana_reg_bit() in AVDK sys_ll.h).
169	 */
170	
171	static int bk7258_ana_reg_bit(uint32_t idx, uint32_t pos, uint32_t mask,
172	                              uint32_t value)
173	{
174	  const uint32_t addr = BK7258_SYS_ANA_REG(idx);
175	  uint32_t v = getreg32(addr);
176	
177	  v &= ~(mask << pos);
178	  v |= ((value & mask) << pos);
179	  return bk7258_ana_reg_write(idx, v);
180	}
181	
182	/* One-shot APLL bring-up (spec §2.2).  cal_val is the family-specific cal
183	 * word; caller decides based on sample rate.
184	 */
185	
186	static int bk7258_apll_program(uint32_t cal_val)
187	{
188	  int ret;
189	
190	  /* Clear the "power-down APLL" bit — active-high in ana_reg5[13]. */
191	
192	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG_APLL_PWD,
193	                           ANA_REG5_PWDAUDPLL_BIT, 0x1u, 0);
194	  if (ret < 0)
195	    {
196	      return ret;
197	    }
198	
199	  ret = bk7258_ana_reg_write(BK7258_ANA_REG26_APLL_CAL, cal_val);
200	  if (ret < 0)
201	    {
202	      return ret;
203	    }
204	
205	  ret = bk7258_ana_reg_write(BK7258_ANA_REG25_APLL_CFG,
206	                             BK7258_APLL_CONFIG_VAL);
207	  if (ret < 0)
208	    {
209	      return ret;
210	    }
211	
212	  /* SPI trigger pulse.  AVDK loops delay(10); we use 200 us as a
213	   * conservative equivalent while APLL locks.
214	   */
215	
216	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG25_APLL_CFG,
217	                           ANA_REG25_SPI_TRIGGER_BIT, 0x1u, 1);
218	  if (ret < 0)
219	    {
220	      return ret;
221	    }
222	
223	  /* AVDK loops delay(10) here (approximately 10 ms on their RTOS tick).
224	   * Waiting only a couple hundred microseconds is not enough for the APLL
225	   * to lock, and the DAC clock silently falls back to a divided XTAL — the
226	   * DAC block appears configured but the FIFO stops draining after a few
227	   * words.  10 ms matches the reference bring-up.
228	   */
229	
230	  up_mdelay(20);
231	
232	  return bk7258_ana_reg_bit(BK7258_ANA_REG25_APLL_CFG,
233	                            ANA_REG25_SPI_TRIGGER_BIT, 0x1u, 0);
234	}
