236	/****************************************************************************
237	 * Public Functions
238	 ****************************************************************************/
239	
240	int bk7258_aud_subsystem_init(void)
241	{
242	  irqstate_t flags;
243	  int ret = OK;
244	
245	  flags = spin_lock_irqsave(&g_bk7258_aud_lock);
246	  if (g_bk7258_aud_subsys_ready)
247	    {
248	      spin_unlock_irqrestore(&g_bk7258_aud_lock, flags);
249	      return OK;
250	    }
251	
252	  spin_unlock_irqrestore(&g_bk7258_aud_lock, flags);
253	
254	  /* CP owns the shared SYS power and SRAM controls and clears them while AP
255	   * is held in reset.  AP must only validate that handoff: writing these
256	   * registers here would race CP power management through whole-word RMWs.
257	   * Fail closed before publishing subsystem readiness if the handoff did not
258	   * take effect.
259	   */
260	
261	  {
262	    uint32_t power = getreg32(BK7258_SYS_POWER_WAKEUP);
263	    uint32_t mem_ctrl1 = getreg32(BK7258_SYS_DEV_MEM_CTRL1);
264	    uint32_t mem_ctrl2 = getreg32(BK7258_SYS_DEV_MEM_CTRL2);
265	
266	    if ((power & BK7258_SYS_AUDP_POWER_DOWN) != 0 ||
267	        (mem_ctrl1 & BK7258_SYS_AUD_MEM_LOW_POWER) != 0 ||
268	        (mem_ctrl2 & BK7258_SYS_AUD_MEM_LOW_POWER) != 0)
269	      {
270	        auderr("BK7258: CP audio wake handoff invalid: "
271	               "pwr=%08lx sd=%08lx ds=%08lx\n",
272	               (unsigned long)power,
273	               (unsigned long)mem_ctrl1,
274	               (unsigned long)mem_ctrl2);
275	        return -EIO;
276	      }
277	  }
278	
279	  /* §2.1 step 2/3: start from XTAL and gate the audio clock on.  The audio
280	   * clock mux is programmed later by bk7258_dac_configure().
281	   */
282	
283	  bk7258_sys_reg_bits(SYS_CLK_DIV_MODE1,
284	                      SYS_CLK_DIV_MODE1_CKSEL_AUD_MASK
285	                          << SYS_CLK_DIV_MODE1_CKSEL_AUD_BIT,
286	                      0u);
287	  bk7258_sys_reg_bits(SYS_CPU_DEVICE_CLK_EN,
288	                      UINT32_C(1) << SYS_CPU_DEVICE_CLK_AUD_CKEN_BIT,
289	                      UINT32_C(1) << SYS_CPU_DEVICE_CLK_AUD_CKEN_BIT);
290	
291	  /* §2.1 step 4: the AUD-block interrupt line is intentionally NOT gated
292	   * here.  Playback goes through GDMA; the driver does not attach any
293	   * handler to BK7258_IRQ_AUDIO, so leaving the sys-ctrl CPU int_en bit
294	   * clear avoids delivering an aggregate audio IRQ that nobody consumes.
295	   */
296	
297	  /* §2.1 step 5: audio block soft-reset via AUD_CLK_CONTROL.
298	   *
299	   * WARNING: bit1 (clk_gate) has inverted semantics — 0 means "gate the
300	   * APB clock" (i.e. no clock reaches the DAC), 1 means "let the clock
301	   * through".  The initial bring-up wrote 0 to the whole register after
302	   * releasing the reset, which silently starved the DAC block of its APB
303	   * clock; the DMA pre-loaded a few FIFO words and then stopped because
304	   * the DAC never requested more data.
305	   *
306	   * Assert reset with clk_gate=1 (clock live), then release reset while
307	   * keeping the clock ungated.
308	   */
309	
310	  putreg32(AUD_CLK_CTRL_SOFT_RESET | AUD_CLK_CTRL_CLK_GATE,
311	           BK7258_AUD_CLK_CONTROL);
312	  up_udelay(10);
313	  putreg32(AUD_CLK_CTRL_CLK_GATE, BK7258_AUD_CLK_CONTROL);
314	
315	  /* §2.1 step 6: apply the pre-computed ana_reg defaults.  These are the
316	   * exact values AVDK's ana_regNN_value_cal() functions produce on
317	   * SOC_BK7236XX; changing them alters bias current, VCM and DAC common
318	   * mode and MUST be re-derived from silicon test data if touched.
319	   */
320	
321	  ret = bk7258_ana_reg_write(BK7258_ANA_REG18, BK7258_ANA_REG18_DEFAULT);
322	  if (ret < 0)
323	    {
324	      goto fail;
325	    }
326	
327	  ret = bk7258_ana_reg_write(BK7258_ANA_REG19, BK7258_ANA_REG19_DEFAULT);
328	  if (ret < 0)
329	    {
330	      goto fail;
331	    }
332	
333	  ret = bk7258_ana_reg_write(BK7258_ANA_REG20, BK7258_ANA_REG20_DEFAULT);
334	  if (ret < 0)
335	    {
336	      goto fail;
337	    }
338	
339	  ret = bk7258_ana_reg_write(BK7258_ANA_REG21, BK7258_ANA_REG21_DEFAULT);
340	  if (ret < 0)
341	    {
342	      goto fail;
343	    }
344	
345	  ret = bk7258_ana_reg_write(BK7258_ANA_REG27, BK7258_ANA_REG27_DEFAULT);
346	  if (ret < 0)
347	    {
348	      goto fail;
349	    }
350	
351	  /* §2.1 step 7: enable the audio bias network AFTER the ana_reg defaults
352	   * have latched.
353	   */
354	
355	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG18,
356	                           ANA_REG18_ENAUDBIAS_BIT, 0x1u, 1);
357	  if (ret < 0)
358	    {
359	      goto fail;
360	    }
361	
362	  flags = spin_lock_irqsave(&g_bk7258_aud_lock);
363	  g_bk7258_aud_subsys_ready = true;
364	  spin_unlock_irqrestore(&g_bk7258_aud_lock, flags);
365	
366	  audinfo("BK7258: audio subsystem initialised\n");
367	  return OK;
368	
369	fail:
370	  auderr("BK7258: audio subsystem init failed: %d\n", ret);
371	  return ret;
372	}
