374	int bk7258_dac_configure(const struct bk7258_dac_cfg_s *cfg)
375	{
376	  irqstate_t flags;
377	  uint32_t v;
378	  int ret;
379	
380	  if (cfg == NULL)
381	    {
382	      return -EINVAL;
383	    }
384	
385	  if (!g_bk7258_aud_subsys_ready)
386	    {
387	      ret = bk7258_aud_subsystem_init();
388	      if (ret < 0)
389	        {
390	          return ret;
391	        }
392	    }
393	
394	  g_bk7258_dac_use_apll = cfg->use_apll;
395	
396	  /* §2.2 clock select. */
397	
398	  if (cfg->use_apll)
399	    {
400	      bk7258_sys_reg_bits(SYS_CLK_DIV_MODE1,
401	                          SYS_CLK_DIV_MODE1_CKSEL_AUD_MASK
402	                              << SYS_CLK_DIV_MODE1_CKSEL_AUD_BIT,
403	                          UINT32_C(1) << SYS_CLK_DIV_MODE1_CKSEL_AUD_BIT);
404	
405	      ret = bk7258_apll_program(BK7258_APLL_CAL_VAL_48K);
406	      if (ret < 0)
407	        {
408	          return ret;
409	        }
410	
411	      v = getreg32(BK7258_AUD_AUDIO_CONFIG);
412	      v |= AUD_AUDIO_CFG_APLL_SEL;
413	      putreg32(v, BK7258_AUD_AUDIO_CONFIG);
414	
415	      /* Divide DMIC clock so it does not steal APLL bandwidth. */
416	
417	      bk7258_sys_reg_bits(SYS_CLK_DIV_MODE2,
418	                          UINT32_C(1) << SYS_CLK_DIV_MODE2_DMIC_DIV_BIT,
419	                          UINT32_C(1) << SYS_CLK_DIV_MODE2_DMIC_DIV_BIT);
420	    }
421	  else
422	    {
423	      bk7258_sys_reg_bits(SYS_CLK_DIV_MODE1,
424	                          SYS_CLK_DIV_MODE1_CKSEL_AUD_MASK
425	                              << SYS_CLK_DIV_MODE1_CKSEL_AUD_BIT,
426	                          0u);
427	
428	      v = getreg32(BK7258_AUD_AUDIO_CONFIG);
429	      v &= ~AUD_AUDIO_CFG_APLL_SEL;
430	      putreg32(v, BK7258_AUD_AUDIO_CONFIG);
431	    }
432	
433	  /* §2.3 step 4: DAC analog path power-up.  On BK7258 (SOC_BK7236XX) the
434	   * BK7256-era right-channel/vdd rails are not-supported no-ops in AVDK;
435	   * we only drive the fields that actually map to silicon.
436	   *
437	   *   dac_bias_en  → ana_reg21[enbs]        (not exposed here, latched by
438	   *                                          the ana_reg21 default value)
439	   *   dac_drv_en   → ana_reg20[dacdrven]
440	   *   dac_dcoc_en  → ana_reg20[lendcoc]
441	   *   dac_idac_en  → ana_reg21[enidacl]
442	   *   dacl_en      → ana_reg20[daclen]
443	   *   diffen       → ana_reg20[diffen]
444	   */
445	
446	  /* AVDK aud_dac_driver.c:81..87 explicitly flips these four bits in this
447	   * order.  ana_reg21.enbs (dac bias) is NOT part of the reset default
448	   * value we programmed earlier and MUST be raised now.
449	   */
450	
451	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG21,
452	                           ANA_REG21_ENBS_BIT, 0x1u, 1);
453	  if (ret < 0)
454	    {
455	      return ret;
456	    }
457	
458	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG20,
459	                           ANA_REG20_DACDRVEN_BIT, 0x1u, 1);
460	  if (ret < 0)
461	    {
462	      return ret;
463	    }
464	
465	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG20,
466	                           ANA_REG20_LENDCOC_BIT, 0x1u, 1);
467	  if (ret < 0)
468	    {
469	      return ret;
470	    }
471	
472	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG21,
473	                           ANA_REG21_ENIDACL_BIT, 0x1u, 1);
474	  if (ret < 0)
475	    {
476	      return ret;
477	    }
478	
479	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG20,
480	                           ANA_REG20_DACLEN_BIT, 0x1u, 1);
481	  if (ret < 0)
482	    {
483	      return ret;
484	    }
485	
486	  /* §2.3 step 6: differential vs single-ended. */
487	
488	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG20,
489	                           ANA_REG20_DIFFEN_BIT, 0x1u,
490	                           cfg->work_mode == BK7258_DAC_WORK_DIFFEN
491	                                             ? 1u : 0u);
492	  if (ret < 0)
493	    {
494	      return ret;
495	    }
496	
497	  /* §2.3 step 7: DAC digital path.  Gain, HPF bypass, clk invert. */
498	
499	  flags = spin_lock_irqsave(&g_bk7258_aud_lock);
500	  v = getreg32(BK7258_AUD_DAC_CONFIG0);
501	  v &= ~(AUD_DAC_CFG0_GAIN_MASK | AUD_DAC_CFG0_CLK_INVERT
502	         | AUD_DAC_CFG0_HPF1_BYPASS | AUD_DAC_CFG0_HPF2_BYPASS);
503	  v |= ((uint32_t)(cfg->gain & 0x3Fu) << AUD_DAC_CFG0_GAIN_SHIFT);
504	  v |= AUD_DAC_CFG0_HPF1_BYPASS | AUD_DAC_CFG0_HPF2_BYPASS;
505	  putreg32(v, BK7258_AUD_DAC_CONFIG0);
506	  spin_unlock_irqrestore(&g_bk7258_aud_lock, flags);
507	
508	  /* §2.4: FIFO read threshold.  With threshold=0 the audio block only
509	   * asserts a DMA request when the FIFO is completely empty; on a 32-word
510	   * FIFO that is one request per 32 samples, and combined with any DMA
511	   * arbitration latency the FIFO under-runs and stops requesting.  AVDK
512	   * uses 4 for BK7256; 8 leaves comfortable headroom on BK7258.
513	   */
514	
515	  {
516	    uint32_t fifo_cfg;
517	    fifo_cfg  = getreg32(BK7258_AUD_FIFO_CONFIG);
518	    fifo_cfg &= ~(AUD_FIFO_CFG_DACL_RD_TH_MASK
519	                  | AUD_FIFO_CFG_DACR_RD_TH_MASK);
520	    fifo_cfg |= (UINT32_C(8) << AUD_FIFO_CFG_DACL_RD_TH_SHIFT);
521	    fifo_cfg |= (UINT32_C(8) << AUD_FIFO_CFG_DACR_RD_TH_SHIFT);
522	    putreg32(fifo_cfg, BK7258_AUD_FIFO_CONFIG);
523	  }
524	
525	  /* §2.3 step 8: sample-rate divider. */
526	
527	  ret = bk7258_dac_set_sample_rate(cfg->samp_rate);
528	  if (ret < 0)
529	    {
530	      return ret;
531	    }
532	
533	  /* §2.3 step 9: previously we muted the DAC here.  Empirically the DAC
534	   * FIFO then never fully drains after start() unmutes; leaving the DAC
535	   * un-muted through configure() lets DMA replenish the FIFO immediately.
536	   */
537	
538	  g_bk7258_dac_configured = true;
539	  return OK;
540	}
