542	int bk7258_dac_set_sample_rate(uint32_t samp_rate)
543	{
544	  uint32_t sr_code;
545	  uint32_t fracmod = 0;
546	  bool     fracmod_manual = false;
547	  bool     apll_44k_family = false;
548	  uint32_t v;
549	  int ret;
550	
551	  switch (samp_rate)
552	    {
553	      case 8000:
554	        sr_code = AUD_SAMP_RATE_8K;
555	        break;
556	
557	      case 16000:
558	        sr_code = AUD_SAMP_RATE_16K;
559	        break;
560	
561	      case 44100:
562	        sr_code = AUD_SAMP_RATE_44_1K;
563	        apll_44k_family = true;
564	        break;
565	
566	      case 48000:
567	        sr_code = AUD_SAMP_RATE_48K;
568	        break;
569	
570	      case 11025:
571	        sr_code = AUD_SAMP_RATE_44_1K;
572	        fracmod = BK7258_AUD_CONST_DIV_44_1K << 2;
573	        fracmod_manual = true;
574	        apll_44k_family = true;
575	        break;
576	
577	      case 22050:
578	        sr_code = AUD_SAMP_RATE_44_1K;
579	        fracmod = BK7258_AUD_CONST_DIV_44_1K << 1;
580	        fracmod_manual = true;
581	        apll_44k_family = true;
582	        break;
583	
584	      case 12000:
585	        sr_code = AUD_SAMP_RATE_48K;
586	        fracmod = BK7258_AUD_CONST_DIV_48K << 2;
587	        fracmod_manual = true;
588	        break;
589	
590	      case 24000:
591	        sr_code = AUD_SAMP_RATE_48K;
592	        fracmod = BK7258_AUD_CONST_DIV_48K << 1;
593	        fracmod_manual = true;
594	        break;
595	
596	      case 32000:
597	        sr_code = AUD_SAMP_RATE_16K;
598	        fracmod = BK7258_AUD_CONST_DIV_16K >> 1;
599	        fracmod_manual = true;
600	        break;
601	
602	      default:
603	        auderr("BK7258: unsupported sample rate %lu\n",
604	               (unsigned long)samp_rate);
605	        return -EINVAL;
606	    }
607	
608	  /* On APLL, the 44.1k family requires a different cal value.  Re-run the
609	   * APLL bring-up transparently.
610	   */
611	
612	  if (g_bk7258_dac_use_apll)
613	    {
614	      ret = bk7258_apll_program(apll_44k_family
615	                                    ? BK7258_APLL_CAL_VAL_44_1K
616	                                    : BK7258_APLL_CAL_VAL_48K);
617	      if (ret < 0)
618	        {
619	          return ret;
620	        }
621	    }
622	
623	  /* Program fracmod first (upper half), then the samp_rate_DAC bits.  This
624	   * mirrors AVDK ordering and avoids a transient rate mismatch on the DAC
625	   * clock.
626	   */
627	
628	  v = getreg32(BK7258_AUD_EXTEND_CFG);
629	  v &= ~AUD_EXT_CFG_DAC_FRACMOD_MAN;
630	  if (fracmod_manual)
631	    {
632	      v |= AUD_EXT_CFG_DAC_FRACMOD_MAN;
633	    }
634	
635	  putreg32(v, BK7258_AUD_EXTEND_CFG);
636	
637	  if (fracmod_manual)
638	    {
639	      putreg32(fracmod, BK7258_AUD_DAC_FRACMOD);
640	    }
641	
642	  v = getreg32(BK7258_AUD_AUDIO_CONFIG);
643	  v &= ~AUD_AUDIO_CFG_SAMP_RATE_MASK;
644	  v |= (sr_code << AUD_AUDIO_CFG_SAMP_RATE_SHIFT)
645	       & AUD_AUDIO_CFG_SAMP_RATE_MASK;
646	  putreg32(v, BK7258_AUD_AUDIO_CONFIG);
647	
648	  return OK;
649	}
