735	void bk7258_dac_deinit(void)
736	{
737	  uint32_t v;
738	
739	  bk7258_dac_stop();
740	  (void)bk7258_dac_mute(true);
741	
742	  /* Reverse the analog power-up sequence.  Keep the ana_reg defaults in
743	   * place so a future bk7258_dac_configure() does not have to re-run the
744	   * whole subsystem init.
745	   */
746	
747	  (void)bk7258_ana_reg_bit(BK7258_ANA_REG20, ANA_REG20_DACLEN_BIT, 0x1u, 0);
748	  (void)bk7258_ana_reg_bit(BK7258_ANA_REG21, ANA_REG21_ENIDACL_BIT, 0x1u, 0);
749	  (void)bk7258_ana_reg_bit(BK7258_ANA_REG20, ANA_REG20_LENDCOC_BIT, 0x1u, 0);
750	  (void)bk7258_ana_reg_bit(BK7258_ANA_REG20, ANA_REG20_DACDRVEN_BIT, 0x1u, 0);
751	
752	  /* Restore the vendor deinit clock baseline: select XTAL in both the SYS
753	   * mux and AUD block, clear the APLL-only DMIC divider, then power APLL
754	   * down.  This makes the next configure independent of the previous one.
755	   */
756	
757	  v = getreg32(BK7258_AUD_AUDIO_CONFIG);
758	  v &= ~AUD_AUDIO_CFG_APLL_SEL;
759	  putreg32(v, BK7258_AUD_AUDIO_CONFIG);
760	  bk7258_sys_reg_bits(SYS_CLK_DIV_MODE1,
761	                      SYS_CLK_DIV_MODE1_CKSEL_AUD_MASK
762	                          << SYS_CLK_DIV_MODE1_CKSEL_AUD_BIT,
763	                      0u);
764	  bk7258_sys_reg_bits(SYS_CLK_DIV_MODE2,
765	                      UINT32_C(1) << SYS_CLK_DIV_MODE2_DMIC_DIV_BIT,
766	                      0u);
767	  (void)bk7258_ana_reg_bit(BK7258_ANA_REG_APLL_PWD,
768	                           ANA_REG5_PWDAUDPLL_BIT, 0x1u, 1u);
769	
770	  g_bk7258_dac_use_apll  = false;
771	  g_bk7258_dac_configured = false;
772	}
