772	static int bk7258_shutdown(FAR struct audio_lowerhalf_s *dev)
773	{
774	  FAR struct bk7258_audio_s *priv = (FAR struct bk7258_audio_s *)dev;
775	  FAR struct ap_buffer_s *apb;
776	  irqstate_t flags;
777	  int error;
778	  int pa_ret;
779	
780	  /* Temporarily close every producer/run gate before touching hardware.
781	   * Queueing LPWORK is serialized by this same lock.  The barrier is lifted
782	   * only after IRQ/worker teardown and all owned buffers are returned.
783	   */
784	
785	  flags = spin_lock_irqsave(&priv->lock);
786	  priv->closing = true;
787	  priv->dac_running = false;
788	  priv->dma_active = false;
789	  priv->complete_pending = false;
790	  priv->underrun_pending = false;
791	  priv->final_seen = false;
792	  error = priv->dma_error < 0 ? priv->dma_error : -ESHUTDOWN;
793	  spin_unlock_irqrestore(&priv->lock, flags);
794	
795	  /* Stop the IRQ producer first, then synchronously cover any worker queued
796	   * before closing became visible.  Neither operation runs under a spinlock.
797	   */
798	
799	  if (priv->dma_ch >= 0)
800	    {
801	      bk7258_gdma_stop(priv->dma_ch);
802	    }
803	
804	  (void)work_cancel_sync(LPWORK, &priv->work);
805	
806	  if (priv->configured)
807	    {
808	      (void)bk7258_dac_mute(true);
809	    }
810	
811	  bk7258_dac_stop();
812	  pa_ret = bk7258_pa_disable();
813	  if (pa_ret < 0)
814	    {
815	      AUD_ERR("PA disable during shutdown failed: %d", pa_ret);
816	    }
817	
818	  if (priv->dma_ch >= 0)
819	    {
820	      bk7258_gdma_free(priv->dma_ch);
821	      priv->dma_ch = -1;
822	    }
823	
824	  if (priv->configured)
825	    {
826	      bk7258_dac_deinit();
827	    }
828	
829	  /* audio_close keeps upper->status alive until shutdown returns.  Return
830	   * all lower-owned buffers synchronously; callback refill attempts observe
831	   * closing and are rejected without transferring ownership back to us.
832	   */
833	
834	  for (; ; )
835	    {
836	      flags = spin_lock_irqsave(&priv->lock);
837	      apb = (FAR struct ap_buffer_s *)dq_remfirst(&priv->doneq);
838	      spin_unlock_irqrestore(&priv->lock, flags);
839	      if (apb == NULL)
840	        {
841	          break;
842	        }
843	
844	      bk7258_notify_dequeue(priv, apb, OK);
845	    }
846	
847	  for (; ; )
848	    {
849	      flags = spin_lock_irqsave(&priv->lock);
850	      apb = (FAR struct ap_buffer_s *)dq_remfirst(&priv->pendq);
851	      spin_unlock_irqrestore(&priv->lock, flags);
852	      if (apb == NULL)
853	        {
854	          break;
855	        }
856	
857	      bk7258_notify_dequeue(priv, apb, -ESHUTDOWN);
858	    }
859	
860	  for (; ; )
861	    {
862	      flags = spin_lock_irqsave(&priv->lock);
863	      apb = (FAR struct ap_buffer_s *)dq_remfirst(&priv->failq);
864	      spin_unlock_irqrestore(&priv->lock, flags);
865	      if (apb == NULL)
866	        {
867	          break;
868	        }
869	
870	      bk7258_notify_dequeue(priv, apb, error);
871	    }
872	
873	  /* GDMA is stopped/freed and work_cancel_sync has covered every queued
874	   * worker, so no IRQ or worker can observe the fault reset below.  Keep the
875	   * normal stop gate closed until the next successful OUTPUT configure, but
876	   * make the registered lower half reusable by a future open.
877	   */
878	
879	  flags = spin_lock_irqsave(&priv->lock);
880	  priv->configured = false;
881	  priv->closing = false;
882	  priv->stopping = true;
883	  priv->faulted = false;
884	  priv->fault_pending = false;
885	  priv->recover_after_fault = false;
886	  priv->complete_pending = false;
887	  priv->underrun_pending = false;
888	  priv->final_seen = false;
889	  priv->dma_error = OK;
890	  spin_unlock_irqrestore(&priv->lock, flags);
891	
892	  return OK;
893	}
894	
895	#ifdef CONFIG_AUDIO_MULTI_SESSION
896	static int bk7258_start(FAR struct audio_lowerhalf_s *dev,
897	                        FAR void *session)
898	#else
899	static int bk7258_start(FAR struct audio_lowerhalf_s *dev)
900	#endif
901	{
902	  FAR struct bk7258_audio_s *priv = (FAR struct bk7258_audio_s *)dev;
903	  struct bk7258_dac_cfg_s dac_cfg;
904	  irqstate_t flags;
905	  bool notify_fault = false;
906	  int pa_ret;
907	  int ret;
908	
909	#ifdef CONFIG_AUDIO_MULTI_SESSION
910	  (void)session;
911	#endif
912	
913	  flags = spin_lock_irqsave(&priv->lock);
914	  if (priv->closing)
915	    {
916	      spin_unlock_irqrestore(&priv->lock, flags);
917	      return -ESHUTDOWN;
918	    }
919	
920	  if (priv->stopping || priv->fault_pending)
921	    {
922	      spin_unlock_irqrestore(&priv->lock, flags);
923	      return -EBUSY;
924	    }
925	
926	  if (priv->faulted)
927	    {
928	      ret = priv->dma_error < 0 ? priv->dma_error : -EIO;
929	      spin_unlock_irqrestore(&priv->lock, flags);
930	      return ret;
931	    }
932	
933	  if (priv->dac_running)
934	    {
935	      spin_unlock_irqrestore(&priv->lock, flags);
936	      return OK;
937	    }
938	
939	  spin_unlock_irqrestore(&priv->lock, flags);
940	
941	  /* Program the DAC block.  Start muted; unmute happens only after PA
942	   * enable and both of its board-owned settling delays succeed.
943	   */
944	
945	  dac_cfg.samp_rate = priv->sample_rate;
946	  dac_cfg.channel   = BK7258_DAC_CHL_LR;
947	  dac_cfg.work_mode = BK7258_DAC_WORK_DIFFEN;
948	  dac_cfg.gain      = 0;
949	  dac_cfg.use_apll  = true;
950	
951	  ret = bk7258_dac_configure(&dac_cfg);
952	  if (ret < 0)
953	    {
954	      AUD_ERR("dac_configure failed: %d", ret);
955	
956	      /* configure powers the analog path incrementally.  Roll back even
957	       * though configured was never published, so an intermediate failure
958	       * cannot leave DAC rails enabled.
959	       */
960	
961	      (void)bk7258_dac_mute(true);
962	      bk7258_dac_stop();
963	      pa_ret = bk7258_pa_disable();
964	      if (pa_ret < 0)
965	        {
966	          AUD_ERR("PA disable after DAC configure failure: %d", pa_ret);
967	        }
968	
969	      bk7258_dac_deinit();
970	      flags = spin_lock_irqsave(&priv->lock);
971	      priv->configured = false;
972	      priv->dma_active = false;
973	      spin_unlock_irqrestore(&priv->lock, flags);
974	      return ret;
975	    }
976	
977	  /* The chip configure path may leave the digital DAC unmuted.  Assert mute
978	   * immediately, before publishing configured or enabling the PA.
979	   */
980	
981	  ret = bk7258_dac_mute(true);
982	  if (ret < 0)
983	    {
984	      AUD_ERR("dac_mute failed after configure: %d", ret);
985	      goto errout;
986	    }
987	
988	  flags = spin_lock_irqsave(&priv->lock);
989	  priv->configured = true;
990	  spin_unlock_irqrestore(&priv->lock, flags);
991	
992	  if (priv->dma_ch < 0)
993	    {
994	      priv->dma_ch = bk7258_gdma_alloc();
995	      if (priv->dma_ch < 0)
996	        {
997	          ret = priv->dma_ch;
998	          AUD_ERR("gdma_alloc failed: %d", ret);
999	          goto errout;
1000	        }
1001	    }
1002	
1003	  /* Settle the PA while the configured DAC is still muted and before the
1004	   * run gate allows any DMA transfer.  This avoids consuming queued audio
1005	   * during the board-owned delays and leaves no asynchronous DMA fault for
1006	   * start() to race with.
1007	   */
1008	
1009	  ret = bk7258_pa_enable();
1010	  if (ret < 0)
1011	    {
1012	      AUD_ERR("PA enable failed: %d", ret);
1013	      goto errout;
1014	    }
1015	
1016	  flags = spin_lock_irqsave(&priv->lock);
1017	  if (priv->closing || priv->stopping || priv->faulted ||
1018	      priv->fault_pending)
1019	    {
1020	      ret = priv->closing ? -ESHUTDOWN :
1021	            (priv->faulted && priv->dma_error < 0 ? priv->dma_error :
1022	             -EBUSY);
1023	      spin_unlock_irqrestore(&priv->lock, flags);
1024	      goto errout;
1025	    }
1026	
1027	  priv->dac_running = true;
1028	  priv->dma_active = false;
1029	  priv->underrun_pending = false;
1030	
1031	  ret = bk7258_start_next_locked(priv);
1032	  if (ret < 0)
1033	    {
1034	      bk7258_fault_locked(priv, ret, true);
1035	      notify_fault = true;
1036	      spin_unlock_irqrestore(&priv->lock, flags);
1037	      goto errout;
1038	    }
1039	
1040	  /* These are non-sleeping register operations.  Keep IRQs disabled until
1041	   * the DAC is started and volume applied so no DMA fault can close the run
1042	   * gate between the final state check and unmute.
1043	   */
1044	
1045	  bk7258_dac_start();
1046	  ret = bk7258_apply_volume(priv);
1047	  if (ret < 0)
1048	    {
1049	      AUD_ERR("apply volume during start failed: %d", ret);
1050	      bk7258_fault_locked(priv, ret, true);
1051	      notify_fault = true;
1052	      spin_unlock_irqrestore(&priv->lock, flags);
1053	      goto errout;
1054	    }
1055	
1056	  spin_unlock_irqrestore(&priv->lock, flags);
1057	  return OK;
1058	
1059	errout:
1060	  /* Complete rollback.  PA disable errors are diagnostic only here: the
1061	   * initiating start error remains the caller-visible result.
1062	   */
1063	
1064	  (void)bk7258_dac_mute(true);
1065	  pa_ret = bk7258_pa_disable();
1066	  if (pa_ret < 0)
1067	    {
1068	      AUD_ERR("PA disable during start rollback failed: %d", pa_ret);
1069	    }
1070	
1071	  bk7258_dac_stop();
1072	  if (priv->dma_ch >= 0)
1073	    {
1074	      bk7258_gdma_stop(priv->dma_ch);
1075	      bk7258_gdma_free(priv->dma_ch);
1076	      priv->dma_ch = -1;
1077	    }
1078	
1079	  bk7258_dac_deinit();
1080	
1081	  flags = spin_lock_irqsave(&priv->lock);
1082	  priv->configured = false;
1083	  priv->dma_active = false;
1084	  if (notify_fault)
1085	    {
1086	      bk7258_schedule_worker_locked(priv);
1087	    }
1088	
1089	  spin_unlock_irqrestore(&priv->lock, flags);
1090	  return ret;
1091	}
1092	
1093	#ifndef CONFIG_AUDIO_EXCLUDE_STOP
1094	#ifdef CONFIG_AUDIO_MULTI_SESSION
1095	static int bk7258_stop(FAR struct audio_lowerhalf_s *dev,
1096	                       FAR void *session)
1097	#else
1098	static int bk7258_stop(FAR struct audio_lowerhalf_s *dev)
1099	#endif
1100	{
1101	  FAR struct bk7258_audio_s *priv = (FAR struct bk7258_audio_s *)dev;
1102	  FAR struct ap_buffer_s *apb;
1103	  irqstate_t flags;
1104	  int pa_ret;
1105	
1106	#ifdef CONFIG_AUDIO_MULTI_SESSION
1107	  (void)session;
1108	#endif
1109	
1110	  /* stopping remains asserted through asynchronous DEQUEUE/COMPLETE so an
1111	   * upper-half refill caused by those callbacks cannot be reacquired.  A
1112	   * later successful OUTPUT configure opens this gate again.
1113	   */
1114	
1115	  flags = spin_lock_irqsave(&priv->lock);
1116	  if (priv->closing)
1117	    {
1118	      spin_unlock_irqrestore(&priv->lock, flags);
1119	      return -ESHUTDOWN;
1120	    }
1121	
1122	  priv->stopping = true;
1123	  priv->dac_running = false;
1124	  priv->dma_active = false;
1125	  priv->complete_pending = false;
1126	  priv->underrun_pending = false;
1127	  priv->final_seen = false;
1128	  spin_unlock_irqrestore(&priv->lock, flags);
1129	
1130	  if (priv->configured)
1131	    {
1132	      (void)bk7258_dac_mute(true);
1133	    }
1134	
1135	  if (priv->dma_ch >= 0)
1136	    {
1137	      bk7258_gdma_stop(priv->dma_ch);
1138	    }
1139	
1140	  bk7258_dac_stop();
1141	  pa_ret = bk7258_pa_disable();
1142	  if (pa_ret < 0)
1143	    {
1144	      AUD_ERR("PA disable during stop failed: %d", pa_ret);
1145	    }
1146	
1147	  flags = spin_lock_irqsave(&priv->lock);
1148	
1149	  /* Return every normally stopped buffer successfully.  Buffers already
1150	   * detached into failq retain their asynchronous error result.
1151	   */
1152	
1153	  while ((apb = (FAR struct ap_buffer_s *)dq_remfirst(&priv->pendq)) != NULL)
1154	    {
1155	      dq_addlast(&apb->dq_entry, &priv->doneq);
1156	    }
1157	
1158	  priv->complete_pending = true;
1159	  bk7258_schedule_worker_locked(priv);
1160	  spin_unlock_irqrestore(&priv->lock, flags);
1161	  return OK;
1162	}
1163	#endif
1164	
1165	static int bk7258_enqueuebuffer(FAR struct audio_lowerhalf_s *dev,
1166	                                FAR struct ap_buffer_s *apb)
1167	{
1168	  FAR struct bk7258_audio_s *priv = (FAR struct bk7258_audio_s *)dev;
1169	  irqstate_t flags;
1170	  int ret;
1171	
1172	  DEBUGASSERT(priv && apb);
1173	
1174	  flags = spin_lock_irqsave(&priv->lock);
1175	
1176	  /* Rejection happens before ownership transfer.  In particular, faulted
1177	   * remains latched while error callbacks make upper-half refill attempts.
1178	   */
1179	
1180	  if (priv->closing)
1181	    {
1182	      ret = -ESHUTDOWN;
1183	      goto reject;
1184	    }
1185	
1186	  if (priv->stopping || priv->fault_pending)
1187	    {
1188	      ret = -EBUSY;
1189	      goto reject;
1190	    }
1191	
1192	  if (priv->faulted)
1193	    {
1194	      ret = priv->dma_error < 0 ? priv->dma_error : -EIO;
1195	      goto reject;
1196	    }
1197	
1198	  if ((apb->flags & AUDIO_APB_FINAL) != 0u)
1199	    {
1200	      priv->final_seen = true;
1201	    }
1202	
1203	  dq_addlast(&apb->dq_entry, &priv->pendq);
1204	
1205	  /* Once queued, ownership has transferred.  A synchronous start failure is
1206	   * reported asynchronously by error DEQUEUE; returning an error here as
1207	   * well would make ownership ambiguous to the upper half.
1208	   */
1209	
1210	  if (priv->dac_running && !priv->dma_active)
1211	    {
1212	      ret = bk7258_start_next_locked(priv);
1213	      if (ret < 0)
1214	        {
1215	          bk7258_fault_locked(priv, ret, false);
1216	          bk7258_schedule_worker_locked(priv);
1217	        }
1218	    }
1219	
1220	  spin_unlock_irqrestore(&priv->lock, flags);
1221	  return OK;
1222	
1223	reject:
1224	  spin_unlock_irqrestore(&priv->lock, flags);
1225	  return ret;
1226	}
