1307	  if (priv == NULL)
1308	    {
1309	      AUD_ERR("alloc failed");
1310	      return -ENOMEM;
1311	    }
1312	
1313	  priv->dev.ops     = &g_bk7258_playback_ops;
1314	  priv->type        = BK7258_AUDIO_TYPE_PLAYBACK;
1315	  priv->sample_rate = BK7258_AUDIO_DEFAULT_SAMPLE_RATE;
