1317	  priv->bpsamp      = BK7258_AUDIO_DEFAULT_BPSAMP;
1318	  priv->volume      = BK7258_AUDIO_DEFAULT_VOLUME;
1319	  priv->mute        = false;
1320	  priv->dma_ch      = -1;
1321	  spin_lock_init(&priv->lock);
1322	  dq_init(&priv->pendq);
1323	  dq_init(&priv->doneq);
1324	  dq_init(&priv->failq);
1325	
1326	  /* Bring the GDMA subsystem up eagerly so the first start() does not have
1327	   * to serialise on it inside the audio-open critical path.
1328	   */
1329	
1330	  ret = bk7258_gdma_initialize();
1331	  if (ret < 0)
1332	    {
1333	      AUD_ERR("gdma_initialize failed: %d", ret);
1334	      kmm_free(priv);
