1336	    }
1337	
1338	  ret = audio_register("pcm0p", &priv->dev);
1339	  if (ret < 0)
1340	    {
1341	      AUD_ERR("audio_register failed: %d", ret);
1342	      kmm_free(priv);
1343	      return ret;
1344	    }
1345	
1346	  AUD_INFO("registered /dev/audio/pcm0p");
1347	  return OK;
1348	}
