2	 * chips/bk7258/audio/bk7258_gdma.c
3	 *
4	 * Minimal BK7258 General DMA (unit 0) driver for audio playback.  See
5	 * bk7258_gdma.h and BK7258_DAC_INIT_SEQUENCE.md §2.4 for context.
6	 *
7	 * Derived from Apache-2.0 code in bk_avdk_smp/:
8	 *   - middleware/soc/bk7258_ap/soc/dma_struct.h  (register layout)
9	 *   - middleware/soc/bk7258_ap/soc/dma_reg.h     (request-mux IDs)
10	 *   - middleware/soc/bk7258_ap/hal/dma_ll.h      (field encodings)
11	 *   - middleware/driver/general_dma/dma_driver.c (channel lifecycle)
12	 ****************************************************************************/
13	
14	#include <nuttx/config.h>
15	
16	#include <debug.h>
17	#include <errno.h>
18	#include <stdbool.h>
19	#include <stdint.h>
20	#include <string.h>
21	
22	#include <nuttx/arch.h>
23	#include <nuttx/irq.h>
24	#include <nuttx/spinlock.h>
