32	/****************************************************************************
33	 * Pre-processor Definitions
34	 ****************************************************************************/
35	
36	#define BK7258_DMA0_BASE           UINT32_C(0x45020000)
37	#define BK7258_GDMA_CHANNELS       8
38	
39	/* Global (per-unit) offsets, word index * 4. */
40	
41	#define BK7258_DMA_PRIO_MODE       (BK7258_DMA0_BASE + (0x02u * 4u))
42	#define BK7258_DMA_SECURE_ATTR     (BK7258_DMA0_BASE + (0x04u * 4u))
43	#define BK7258_DMA_PRIV_ATTR       (BK7258_DMA0_BASE + (0x05u * 4u))
44	#define BK7258_DMA_INT_STATUS0     (BK7258_DMA0_BASE + (0x06u * 4u))
45	#define BK7258_DMA_INT_STATUS1     (BK7258_DMA0_BASE + (0x07u * 4u))
46	#define BK7258_DMA_INT_ALLOCATE    (BK7258_DMA0_BASE + (0x0Au * 4u))
47	
48	#define DMA_PRIO_SOFT_RESET        (UINT32_C(1) << 0)
49	#define DMA_PRIO_BPS_CLK_GATE      (UINT32_C(1) << 1)  /* 0=run, 1=gate */
50	
51	/* Each channel occupies 16 32-bit words starting at word 0x10 + ch*0x10. */
52	
53	#define DMA_CH_BASE(ch)            (BK7258_DMA0_BASE + \
54	                                    ((0x10u + (uint32_t)(ch) * 0x10u) * 4u))
55	#define DMA_CH_CTRL(ch)            (DMA_CH_BASE(ch) + 0x00u)
56	#define DMA_CH_DST_ADDR(ch)        (DMA_CH_BASE(ch) + 0x04u)
57	#define DMA_CH_SRC_ADDR(ch)        (DMA_CH_BASE(ch) + 0x08u)
58	#define DMA_CH_DST_LOOP_END(ch)    (DMA_CH_BASE(ch) + 0x0Cu)
59	#define DMA_CH_DST_LOOP_START(ch)  (DMA_CH_BASE(ch) + 0x10u)
60	#define DMA_CH_SRC_LOOP_END(ch)    (DMA_CH_BASE(ch) + 0x14u)
61	#define DMA_CH_SRC_LOOP_START(ch)  (DMA_CH_BASE(ch) + 0x18u)
62	#define DMA_CH_REQ_MUX(ch)         (DMA_CH_BASE(ch) + 0x1Cu)
63	#define DMA_CH_SRC_PAUSE(ch)       (DMA_CH_BASE(ch) + 0x20u)
64	#define DMA_CH_DST_PAUSE(ch)       (DMA_CH_BASE(ch) + 0x24u)
65	#define DMA_CH_STATUS(ch)          (DMA_CH_BASE(ch) + 0x30u)
66	
67	/* ctrl register bit layout (dma_struct.h). */
68	
69	#define DMA_CTRL_ENABLE            (UINT32_C(1) << 0)
70	#define DMA_CTRL_FIN_INT_EN        (UINT32_C(1) << 1)
71	#define DMA_CTRL_HALF_INT_EN       (UINT32_C(1) << 2)
72	#define DMA_CTRL_MODE_REPEAT       (UINT32_C(1) << 3)
73	#define DMA_CTRL_SRC_WIDTH_SHIFT   4
74	#define DMA_CTRL_DST_WIDTH_SHIFT   6
75	#define DMA_CTRL_WIDTH_MASK        0x3u
76	#define DMA_CTRL_SRC_INC_EN        (UINT32_C(1) << 8)
77	#define DMA_CTRL_DST_INC_EN        (UINT32_C(1) << 9)
78	#define DMA_CTRL_SRC_LOOP_EN       (UINT32_C(1) << 10)
79	#define DMA_CTRL_DST_LOOP_EN       (UINT32_C(1) << 11)
80	#define DMA_CTRL_PRIO_SHIFT        12
81	#define DMA_CTRL_TRANSFER_LEN_SHIFT 16
82	#define DMA_CTRL_TRANSFER_LEN_MASK (UINT32_C(0xFFFF) << 16)
83	
84	/* req_mux register bit layout. */
85	
86	#define DMA_REQ_SRC_MUX_SHIFT      0
87	#define DMA_REQ_DST_MUX_SHIFT      5
88	#define DMA_REQ_MUX_MASK           0x1Fu
89	/* Bit 20 = src_sec_attr, bit 21 = dst_sec_attr, bit 22 = bus_err_int_en
90	 * (per bk_avdk_smp/ap/middleware/soc/bk7258_ap/soc/dma_struct.h).  When the
91	 * DMA is programmed from the TrustZone secure world, both attr bits MUST
92	 * be set or the AHB slave silently drops the transfer without firing the
93	 * finish interrupt.
94	 */
95	#define DMA_REQ_SRC_SEC_ATTR       (UINT32_C(1) << 20)
96	#define DMA_REQ_DST_SEC_ATTR       (UINT32_C(1) << 21)
97	#define DMA_REQ_BUS_ERR_INT_EN     (UINT32_C(1) << 22)
98	
99	/* status register bit layout. */
100	
101	#define DMA_STAT_FIN_INT           (UINT32_C(1) << 18)
102	#define DMA_STAT_HALF_INT          (UINT32_C(1) << 19)
103	#define DMA_STAT_BUS_ERR_INT       (UINT32_C(1) << 20)
104	
105	/* Sys ctrl bits. */
106	
107	#define SYS_CPU_DEVICE_CLK_EN      (BK7258_SYS_BASE + (0xCu * 4u))
108	#define   SYS_CPU_DEVICE_CLK_GDMA_CKEN_BIT   16  /* dma_cken in sys_struct. */
109	
110	/* Per-CPU interrupt enable table.  On BK7258 the sys ctrl exposes one
111	 * "cpu<N>_int_0_31_en" register per physical CPU.  The AP image runs on
112	 * physical CPU1, so we must gate the GDMA interrupt through the CPU1 table
113	 * (reg 0x22).  Writing bit 11 into CPU0's table (reg 0x20) as we did in
114	 * the initial bring-up left the AP silently deaf to every DMA finish IRQ.
115	 */
116	
117	#ifdef CONFIG_BK7258_COMPONENT_AP
118	#  define SYS_CPU_INT_0_31_EN      (BK7258_SYS_BASE + (0x22u * 4u))
119	#else
120	#  define SYS_CPU_INT_0_31_EN      (BK7258_SYS_BASE + (0x20u * 4u))
121	#endif
122	#define   SYS_CPU_INT_GDMA_INT_EN_BIT       11  /* cpu<N>_gdma_int_en. */
123	
124	/****************************************************************************
125	 * Private Types
126	 ****************************************************************************/
127	
128	struct bk7258_gdma_ch_s
129	{
130	  bk7258_dma_cb_t cb;
131	  FAR void       *arg;
132	  bool            in_use;
133	};
