135	/****************************************************************************
136	 * Private Data
137	 ****************************************************************************/
138	
139	static bool                    g_bk7258_gdma_ready;
140	static spinlock_t              g_bk7258_gdma_lock = SP_UNLOCKED;
141	static struct bk7258_gdma_ch_s g_bk7258_gdma_ch[BK7258_GDMA_CHANNELS];
142	
143	/* Diagnostic counters.  IRQ context must not call syslog helpers, so we
144	 * bump a plain counter and let user-space read it back via a proc-like
145	 * accessor (or a debugger).  Values are cheap to inspect from a crash
146	 * dump and prove whether the GDMA IRQ ever fires.
147	 */
148	
149	volatile uint32_t g_bk7258_gdma_isr_count;
150	volatile uint32_t g_bk7258_gdma_finish_count;
