174	  out->cpu_int_en_val = getreg32(SYS_CPU_INT_0_31_EN);
175	  out->dev_clk_en_val = getreg32(SYS_CPU_DEVICE_CLK_EN);
176	  out->prio_mode      = getreg32(BK7258_DMA_PRIO_MODE);
177	  out->int_status0    = getreg32(BK7258_DMA_INT_STATUS0);
178	  out->int_allocate   = getreg32(BK7258_DMA_INT_ALLOCATE);
179	
180	  for (ch = 0; ch < BK7258_GDMA_CHANNELS && ch < 8; ch++)
181	    {
182	      out->ch[ch].ctrl           = getreg32(DMA_CH_CTRL(ch));
183	      out->ch[ch].status         = getreg32(DMA_CH_STATUS(ch));
184	      out->ch[ch].src            = getreg32(DMA_CH_SRC_ADDR(ch));
185	      out->ch[ch].dst            = getreg32(DMA_CH_DST_ADDR(ch));
186	      out->ch[ch].src_loop_start = getreg32(DMA_CH_SRC_LOOP_START(ch));
187	      out->ch[ch].src_loop_end   = getreg32(DMA_CH_SRC_LOOP_END(ch));
188	      out->ch[ch].dst_loop_start = getreg32(DMA_CH_DST_LOOP_START(ch));
189	      out->ch[ch].dst_loop_end   = getreg32(DMA_CH_DST_LOOP_END(ch));
190	      out->ch[ch].reqmux         = getreg32(DMA_CH_REQ_MUX(ch));
