199	
200	static inline void bk7258_gdma_sys_bits(uint32_t addr, uint32_t mask,
201	                                        uint32_t value)
202	{
203	  uint32_t v = getreg32(addr);
204	  v &= ~mask;
205	  v |= (value & mask);
206	  putreg32(v, addr);
207	}
208	
209	static int bk7258_gdma_isr(int irq, FAR void *context, FAR void *arg)
210	{
211	  int ch;
212	
213	  (void)irq;
214	  (void)context;
215	  (void)arg;
216	
217	  g_bk7258_gdma_isr_count++;
218	
219	  for (ch = 0; ch < BK7258_GDMA_CHANNELS; ch++)
220	    {
221	      uint32_t status = getreg32(DMA_CH_STATUS(ch));
222	      uint32_t clear  = status & (DMA_STAT_FIN_INT | DMA_STAT_HALF_INT
223	                                  | DMA_STAT_BUS_ERR_INT);
224	      uint32_t event  = 0;
225	
226	      if (clear == 0)
227	        {
228	          continue;
229	        }
230	
231	      /* W1C: writing 1 to the pending bit clears it. */
232	
233	      putreg32(clear, DMA_CH_STATUS(ch));
234	
235	      if ((clear & DMA_STAT_HALF_INT) != 0u)
236	        {
237	          event |= BK7258_DMA_EVENT_HALF;
238	          g_bk7258_gdma_half_count++;
239	        }
240	
241	      if ((clear & DMA_STAT_FIN_INT) != 0u)
242	        {
243	          event |= BK7258_DMA_EVENT_FULL;
244	          g_bk7258_gdma_finish_count++;
245	        }
246	
247	      if ((clear & DMA_STAT_BUS_ERR_INT) != 0u)
248	        {
249	          event |= BK7258_DMA_EVENT_BUS_ERROR;
250	          g_bk7258_gdma_buserr_count++;
251	        }
252	
253	      if (g_bk7258_gdma_ch[ch].cb != NULL)
254	        {
255	          g_bk7258_gdma_ch[ch].cb(ch, event, g_bk7258_gdma_ch[ch].arg);
256	        }
257	    }
258	
259	  return OK;
260	}
