265	
266	int bk7258_gdma_initialize(void)
267	{
268	  irqstate_t flags;
269	  int ret;
270	
271	  flags = spin_lock_irqsave(&g_bk7258_gdma_lock);
272	  if (g_bk7258_gdma_ready)
273	    {
274	      spin_unlock_irqrestore(&g_bk7258_gdma_lock, flags);
275	      return OK;
276	    }
277	
278	  spin_unlock_irqrestore(&g_bk7258_gdma_lock, flags);
279	
280	  /* Enable GDMA clock in sys ctrl. */
281	
282	  bk7258_gdma_sys_bits(SYS_CPU_DEVICE_CLK_EN,
283	                       UINT32_C(1) << SYS_CPU_DEVICE_CLK_GDMA_CKEN_BIT,
284	                       UINT32_C(1) << SYS_CPU_DEVICE_CLK_GDMA_CKEN_BIT);
285	
286	  /* Initialize the DMA controller with the sequence hardware-verified by
287	   * PR #17 on secure CP: clear the complete prio_mode register first to
288	   * remove any Bootloader-retained priority or bps_clk_gate state, then
289	   * set soft_reset.  The vendor LL leaves soft_reset at 1 in the
290	   * initialized, operational state.
291	   */
292	
293	  putreg32(0, BK7258_DMA_PRIO_MODE);
294	  putreg32(DMA_PRIO_SOFT_RESET, BK7258_DMA_PRIO_MODE);
295	
296	  putreg32(UINT32_C(0xFFF), BK7258_DMA_SECURE_ATTR);
297	  putreg32(UINT32_C(0xFFF), BK7258_DMA_PRIV_ATTR);
298	
299	  /* Route the aggregate GDMA IRQ line into CPU0 and attach a handler. */
300	
301	  bk7258_gdma_sys_bits(SYS_CPU_INT_0_31_EN,
302	                       UINT32_C(1) << SYS_CPU_INT_GDMA_INT_EN_BIT,
303	                       UINT32_C(1) << SYS_CPU_INT_GDMA_INT_EN_BIT);
304	
305	  ret = irq_attach(BK7258_IRQ_GDMA, bk7258_gdma_isr, NULL);
306	  if (ret < 0)
307	    {
308	      auderr("BK7258: gdma irq_attach failed: %d\n", ret);
309	      return ret;
310	    }
311	
312	  up_enable_irq(BK7258_IRQ_GDMA);
313	
314	  syslog(LOG_INFO,
315	         "BK7258 GDMA: irq=%d, cpu_int_en=%p bit=%u\n",
316	         BK7258_IRQ_GDMA, (void *)(uintptr_t)SYS_CPU_INT_0_31_EN,
317	         (unsigned)SYS_CPU_INT_GDMA_INT_EN_BIT);
318	
319	  flags = spin_lock_irqsave(&g_bk7258_gdma_lock);
320	  g_bk7258_gdma_ready = true;
321	  spin_unlock_irqrestore(&g_bk7258_gdma_lock, flags);
322	
323	  audinfo("BK7258: GDMA initialised (8 channels)\n");
324	  return OK;
325	}
