327	bk7258_dma_ch_t bk7258_gdma_alloc(void)
328	{
329	  irqstate_t flags;
330	  int ch;
331	
332	  if (!g_bk7258_gdma_ready)
333	    {
334	      int ret = bk7258_gdma_initialize();
335	      if (ret < 0)
336	        {
337	          return ret;
338	        }
339	    }
340	
341	  flags = spin_lock_irqsave(&g_bk7258_gdma_lock);
342	  for (ch = 0; ch < BK7258_GDMA_CHANNELS; ch++)
343	    {
344	      if (!g_bk7258_gdma_ch[ch].in_use)
345	        {
346	          g_bk7258_gdma_ch[ch].in_use = true;
347	          g_bk7258_gdma_ch[ch].cb     = NULL;
348	          g_bk7258_gdma_ch[ch].arg    = NULL;
349	          spin_unlock_irqrestore(&g_bk7258_gdma_lock, flags);
350	          return ch;
351	        }
352	    }
353	
354	  spin_unlock_irqrestore(&g_bk7258_gdma_lock, flags);
355	  return -EBUSY;
356	}
