358	void bk7258_gdma_free(bk7258_dma_ch_t ch)
359	{
360	  irqstate_t flags;
361	
362	  if (ch < 0 || ch >= BK7258_GDMA_CHANNELS)
363	    {
364	      return;
365	    }
366	
367	  bk7258_gdma_stop(ch);
368	
369	  flags = spin_lock_irqsave(&g_bk7258_gdma_lock);
370	  g_bk7258_gdma_ch[ch].cb     = NULL;
371	  g_bk7258_gdma_ch[ch].arg    = NULL;
372	  g_bk7258_gdma_ch[ch].in_use = false;
373	  spin_unlock_irqrestore(&g_bk7258_gdma_lock, flags);
374	}
375	
376	int bk7258_gdma_start_m2p(bk7258_dma_ch_t ch,
377	                          const struct bk7258_dma_m2p_cfg_s *cfg)
378	{
379	  uint32_t ctrl;
380	  uint32_t reqmux;
381	  uint32_t transfer_len;
382	
383	  if (ch < 0 || ch >= BK7258_GDMA_CHANNELS || cfg == NULL)
384	    {
385	      return -EINVAL;
386	    }
387	
388	  if (cfg->buf == 0 || cfg->buf_len == 0 || cfg->dest == 0)
389	    {
390	      return -EINVAL;
391	    }
392	
393	  if (cfg->src_width > BK7258_DMA_WIDTH_32 ||
394	      cfg->dst_width > BK7258_DMA_WIDTH_32)
395	    {
396	      return -EINVAL;
397	    }
398	
399	  /* transfer_len is a byte count encoded as N - 1, independent of the
400	   * source and destination widths.  This matches the vendor DMA LL and
401	   * keeps the hardware remain_len value in bytes as well.
402	   */
403	
404	  if (cfg->buf_len > 0x10000u)
405	    {
406	      return -EINVAL;
407	    }
408	
409	  transfer_len = cfg->buf_len - 1u;
410	
411	  /* Stash the client callback before we start; the ISR reads it. */
412	
413	  g_bk7258_gdma_ch[ch].cb  = cfg->callback;
414	  g_bk7258_gdma_ch[ch].arg = cfg->arg;
415	
416	  /* Reset the channel to a known state: disable, clear pending IRQs. */
417	
418	  putreg32(0, DMA_CH_CTRL(ch));
419	  putreg32(DMA_STAT_FIN_INT | DMA_STAT_HALF_INT | DMA_STAT_BUS_ERR_INT,
420	           DMA_CH_STATUS(ch));
421	
422	  /* Source: circular buffer in memory, address auto-increment. */
423	
424	  putreg32((uint32_t)cfg->buf,                DMA_CH_SRC_ADDR(ch));
425	  if (!cfg->one_shot)
426	    {
427	      putreg32((uint32_t)cfg->buf,            DMA_CH_SRC_LOOP_START(ch));
428	      putreg32((uint32_t)(cfg->buf + cfg->buf_len),
429	               DMA_CH_SRC_LOOP_END(ch));
430	    }
431	  else
432	    {
433	      putreg32(0, DMA_CH_SRC_LOOP_START(ch));
434	      putreg32(0, DMA_CH_SRC_LOOP_END(ch));
435	    }
436	
437	  /* Destination: peripheral FIFO port, no increment, no loop. */
438	
439	  /* Destination: single 32-bit FIFO port.  Even though the physical
440	   * address must never change, the AVDK reference (onboard_speaker_stream.c
441	   * :461-486) sets dst_addr_inc_en=1 and dst_addr_loop_en=1 with
442	   * end = start + 4 so the DMA controller keeps advancing its internal
443	   * pointer and re-asserts the request line after each beat.  With
444	   * inc=0/loop=0 the controller latches the destination once and stops
445	   * requesting new data after only a few words (observed: remain_len
446	   * frozen at 1021, FIFO empty, no bus error).
447	   */
448	
449	  putreg32((uint32_t)cfg->dest,               DMA_CH_DST_ADDR(ch));
450	  putreg32((uint32_t)cfg->dest,               DMA_CH_DST_LOOP_START(ch));
451	  putreg32((uint32_t)cfg->dest + 4u,          DMA_CH_DST_LOOP_END(ch));
452	
453	  /* Request-mux: source from memory, destination to the peripheral.
454	   * bus-error IRQ on so a stray write surfaces immediately.
455	   */
456	
457	  reqmux = ((uint32_t)BK7258_DMA_REQ_MEM & DMA_REQ_MUX_MASK)
458	                << DMA_REQ_SRC_MUX_SHIFT;
459	  reqmux |= ((uint32_t)cfg->dest_req_mux & DMA_REQ_MUX_MASK)
460	                << DMA_REQ_DST_MUX_SHIFT;
461	  reqmux |= DMA_REQ_BUS_ERR_INT_EN;
462	#ifdef CONFIG_ARCH_TRUSTZONE_SECURE
463	  reqmux |= DMA_REQ_SRC_SEC_ATTR | DMA_REQ_DST_SEC_ATTR;
464	#endif
465	  putreg32(reqmux, DMA_CH_REQ_MUX(ch));
466	
467	  /* ctrl: full IRQ always on, half IRQ + repeat + src loop only for
468	   * circular playback.  One-shot mode fires just the "finish" IRQ when the
469	   * transfer completes and then stops the channel.
470	   */
471	
472	  ctrl  = DMA_CTRL_FIN_INT_EN
473	        | DMA_CTRL_SRC_INC_EN
474	        | DMA_CTRL_DST_INC_EN
475	        | DMA_CTRL_DST_LOOP_EN;
476	
477	  if (!cfg->one_shot)
478	    {
479	      ctrl |= DMA_CTRL_MODE_REPEAT
480	            | DMA_CTRL_HALF_INT_EN
481	            | DMA_CTRL_SRC_LOOP_EN;
482	    }
483	
484	  ctrl |= ((uint32_t)cfg->src_width & DMA_CTRL_WIDTH_MASK)
485	                << DMA_CTRL_SRC_WIDTH_SHIFT;
486	  ctrl |= ((uint32_t)cfg->dst_width & DMA_CTRL_WIDTH_MASK)
487	                << DMA_CTRL_DST_WIDTH_SHIFT;
488	  ctrl |= (transfer_len & 0xFFFFu) << DMA_CTRL_TRANSFER_LEN_SHIFT;
489	  putreg32(ctrl, DMA_CH_CTRL(ch));
490	
491	  /* Flush the source buffer out of D-cache so DMA sees the up-to-date
492	   * PCM samples.  audio lower-half is expected to flush again on each
493	   * enqueue; this call handles the very first period.
494	   */
495	
496	#ifdef CONFIG_ARMV8M_DCACHE
497	  up_clean_dcache(cfg->buf, cfg->buf + cfg->buf_len);
498	#endif
499	
500	  /* Kick it: set the enable bit last. */
501	
502	  ctrl = getreg32(DMA_CH_CTRL(ch));
503	  ctrl |= DMA_CTRL_ENABLE;
504	  putreg32(ctrl, DMA_CH_CTRL(ch));
505	
506	  audinfo("BK7258 GDMA ch%d started: ctrl=0x%08lx src=0x%08lx dst=0x%08lx "
507	          "reqmux=0x%08lx bytes=%lu\n",
508	          ch, (unsigned long)ctrl, (unsigned long)cfg->buf,
509	          (unsigned long)cfg->dest,
510	          (unsigned long)getreg32(DMA_CH_REQ_MUX(ch)),
511	          (unsigned long)cfg->buf_len);
512	
513	  return OK;
514	}
515	
516	void bk7258_gdma_stop(bk7258_dma_ch_t ch)
517	{
518	  uint32_t ctrl;
519	
520	  if (ch < 0 || ch >= BK7258_GDMA_CHANNELS)
521	    {
522	      return;
523	    }
524	
525	  ctrl = getreg32(DMA_CH_CTRL(ch));
526	  ctrl &= ~DMA_CTRL_ENABLE;
527	  putreg32(ctrl, DMA_CH_CTRL(ch));
528	
529	  /* Clear any pending IRQ bits so the next start() begins from a clean
530	   * state.
531	   */
532	
533	  putreg32(DMA_STAT_FIN_INT | DMA_STAT_HALF_INT | DMA_STAT_BUS_ERR_INT,
534	           DMA_CH_STATUS(ch));
535	}
