1	/****************************************************************************
2	 * apps/testing/bk7258_pcm/bk7258_pcm_main.c
3	 *
4	 * Minimal driver-validation utility for the BK7258 internal-DAC audio
5	 * lower-half (/dev/audio/pcm0p).  Generates a fixed-frequency sine wave in
6	 * memory, feeds it into the audio device via AUDIOIOC_ENQUEUEBUFFER and
7	 * waits for AUDIO_MSG_COMPLETE.  Not a functional player.
8	 *
9	 * Usage:
10	 *   bk7258_pcm [-r rate] [-c channels] [-f freq_hz] [-d duration_ms]
11	 *              [-v volume]
12	 *
13	 * Defaults: 48 kHz, stereo, 1 kHz sine, 2000 ms, volume 80.
14	 ****************************************************************************/
15	
