35	#  include <arch/chip/bk7258_gdma.h>
36	#  include <arch/chip/bk7258_dac.h>
37	#endif
38	
39	#define PCM_DEV_PATH  "/dev/audio/pcm0p"
40	#define MQ_NAME       "/bk7258_pcm_mq"
41	
42	static int      g_sample_rate   = 48000;
43	static int      g_channels      = 2;
44	static int      g_freq_hz       = 1000;
45	static int      g_duration_ms   = 2000;
46	static int      g_volume        = 80;
47	static int      g_trace_mode    = 0; /* -T: sample regs instead of mq. */
48	static int      g_fifo_cpu_mode = 0; /* -F: CPU-to-DAC FIFO boundary.  */
49	
50	static void usage(FAR const char *prog)
51	{
52	  fprintf(stderr,
53	          "Usage: %s [-r rate] [-c channels] [-f freq_hz]"
54	          " [-d duration_ms] [-v volume] [-T] [-F]\n", prog);
55	  exit(EXIT_FAILURE);
56	}
57	
58	static void parse_args(int argc, FAR char *argv[])
59	{
60	  int opt;
61	
62	  while ((opt = getopt(argc, argv, "r:c:f:d:v:TFh")) != -1)
63	    {
64	      switch (opt)
65	        {
66	          case 'r': g_sample_rate   = atoi(optarg); break;
67	          case 'c': g_channels      = atoi(optarg); break;
68	          case 'f': g_freq_hz       = atoi(optarg); break;
69	          case 'd': g_duration_ms   = atoi(optarg); break;
70	          case 'v': g_volume        = atoi(optarg); break;
71	          case 'T': g_trace_mode    = 1;            break;
72	          case 'F': g_fifo_cpu_mode = 1;            break;
73	          case 'h':
74	          default:  usage(argv[0]);
75	        }
76	    }
77	}
78	
79	/* Fill an S16_LE buffer with a bounded sine wave at g_freq_hz.  phase is
80	 * carried across buffers so sample-boundary discontinuities do not create
81	 * audible clicks.
82	 */
83	
84	static void fill_sine(FAR int16_t *dst, size_t nsamples,
85	                      FAR double *phase)
86	{
87	  const double step = 2.0 * M_PI * g_freq_hz / (double)g_sample_rate;
88	  const int16_t amp = 20000;   /* headroom below full-scale.            */
89	  size_t i;
90	
91	  for (i = 0; i < nsamples; i += g_channels)
92	    {
93	      int16_t s = (int16_t)(amp * sin(*phase));
94	      int c;
95	
96	      for (c = 0; c < g_channels; c++)
97	        {
98	          dst[i + c] = s;
99	        }
100	
101	      *phase += step;
102	      if (*phase >= 2.0 * M_PI)
103	        {
104	          *phase -= 2.0 * M_PI;
105	        }
106	    }
107	}
108	
109	static int set_volume(int fd, int volume)
110	{
111	  struct audio_caps_desc_s cap;
112	
113	  memset(&cap, 0, sizeof(cap));
114	  cap.caps.ac_len            = sizeof(struct audio_caps_s);
115	  cap.caps.ac_type           = AUDIO_TYPE_FEATURE;
116	  cap.caps.ac_format.hw      = AUDIO_FU_VOLUME;
117	  cap.caps.ac_controls.hw[0] = (uint16_t)volume;
118	  return ioctl(fd, AUDIOIOC_CONFIGURE, (unsigned long)&cap);
119	}
120	
121	int main(int argc, FAR char *argv[])
122	{
123	  struct audio_caps_desc_s cap;
124	  struct ap_buffer_info_s  buf_info;
125	  struct audio_buf_desc_s  buf_desc;
126	  struct mq_attr           mq_attr;
127	  struct audio_msg_s       msg;
128	  FAR struct ap_buffer_s  *apb;
129	  mqd_t                    mq;
130	  ssize_t                  msglen;
131	  unsigned                 prio;
132	  size_t                   total_bytes;
133	  size_t                   bytes_written = 0;
134	  double                   phase = 0.0;
135	  int                      fd;
136	  int                      ret;
137	
138	  parse_args(argc, argv);
139	
140	  printf("bk7258_pcm: %d Hz %dch, %d Hz sine, %d ms, vol=%d\n",
141	         g_sample_rate, g_channels, g_freq_hz, g_duration_ms, g_volume);
142	
143	  /* Special mode: -T just runs the driver up to AUDIOIOC_START, then
144	   * samples the DMA + FIFO state every 5 ms for 40 iterations without
145	   * touching mq_receive.  This isolates "the FIFO is being drained by the
146	   * DAC" vs "everything is truly frozen".
147	   */
148	
149	  fd = open(PCM_DEV_PATH, O_WRONLY);
150	  if (fd < 0)
151	    {
152	      fprintf(stderr, "open(%s) failed: %d\n", PCM_DEV_PATH, errno);
153	      return EXIT_FAILURE;
154	    }
155	  printf("[bk] open ok\n"); fflush(stdout);
156	
157	  mq_attr.mq_maxmsg  = 16;
158	  mq_attr.mq_msgsize = sizeof(struct audio_msg_s);
159	  mq_attr.mq_flags   = 0;
160	  mq_attr.mq_curmsgs = 0;
161	
162	  mq_unlink(MQ_NAME);
163	  mq = mq_open(MQ_NAME, O_RDWR | O_CREAT, 0644, &mq_attr);
164	  if (mq == (mqd_t)-1)
165	    {
166	      fprintf(stderr, "mq_open failed: %d\n", errno);
167	      close(fd);
168	      return EXIT_FAILURE;
169	    }
170	  printf("[bk] mq ok\n"); fflush(stdout);
171	
172	  ret = ioctl(fd, AUDIOIOC_RESERVE, 0);
173	  if (ret < 0)
174	    {
175	      fprintf(stderr, "AUDIOIOC_RESERVE failed: %d\n", errno);
176	      goto cleanup;
177	    }
178	  printf("[bk] reserve ok\n"); fflush(stdout);
179	
180	  memset(&cap, 0, sizeof(cap));
181	  cap.caps.ac_len            = sizeof(struct audio_caps_s);
182	  cap.caps.ac_type           = AUDIO_TYPE_OUTPUT;
183	  cap.caps.ac_channels       = g_channels;
184	  cap.caps.ac_controls.hw[0] = g_sample_rate & 0xFFFFu;
185	  cap.caps.ac_controls.b[3]  = (uint8_t)(g_sample_rate >> 16);
186	  cap.caps.ac_controls.b[2]  = 16;
187	  cap.caps.ac_subtype        = AUDIO_FMT_PCM;
188	
189	  ret = ioctl(fd, AUDIOIOC_CONFIGURE, (unsigned long)&cap);
190	  if (ret < 0)
191	    {
192	      fprintf(stderr, "AUDIOIOC_CONFIGURE(OUTPUT) failed: %d\n", errno);
193	      goto cleanup;
194	    }
195	  printf("[bk] cfg-out ok\n"); fflush(stdout);
196	
197	  ret = set_volume(fd, g_volume);
198	  if (ret < 0)
199	    {
200	      fprintf(stderr, "set_volume failed: %d (continuing)\n", errno);
201	    }
202	  printf("[bk] vol ok\n"); fflush(stdout);
203	
204	#ifdef CONFIG_AUDIO_BK7258
205	  if (g_fifo_cpu_mode)
206	    {
207	      static const char *const clock_name[] = {"XTAL", "APLL"};
208	      struct bk7258_dac_cfg_s   dac_cfg;
209	      struct bk7258_dac_stats_s snap[2][3];
210	
211	      /* Run both functional clock sources in one boot.  This keeps GDMA
212	       * unallocated and separates a dead APLL from a dead AUDP/FPORT path
213	       * without requiring another diagnostic firmware round-trip.
214	       */
215	
216	      dac_cfg.samp_rate = (uint32_t)g_sample_rate;
217	      dac_cfg.channel   = BK7258_DAC_CHL_LR;
218	      dac_cfg.work_mode = BK7258_DAC_WORK_DIFFEN;
219	      dac_cfg.gain      = 0;
220	
221	      ret = bk7258_aud_subsystem_init();
222	      if (ret < 0)
223	        {
224	          fprintf(stderr, "[bk] FIFOCPU subsystem init failed: %d\n", ret);
225	          goto cleanup;
226	        }
227	
228	      for (int phase = 0; phase < 2; phase++)
229	        {
230	          /* Flush the digital FIFOs before each phase so a failed clock
231	           * source cannot contaminate the following source's snapshots.
232	           */
233	
234	          bk7258_dac_reset_data_path();
235	          dac_cfg.use_apll = phase != 0;
236	          ret = bk7258_dac_configure(&dac_cfg);
237	          if (ret < 0)
238	            {
239	              fprintf(stderr, "[bk] FIFOCPU %s configure failed: %d\n",
240	                      clock_name[phase], ret);
241	              bk7258_dac_deinit();
242	              goto cleanup;
243	            }
244	
245	          ret = bk7258_dac_mute(false);
246	          if (ret < 0)
247	            {
248	              fprintf(stderr, "[bk] FIFOCPU %s unmute failed: %d\n",
249	                      clock_name[phase], ret);
250	              bk7258_dac_deinit();
251	              goto cleanup;
252	            }
253	
254	          bk7258_dac_start();
255	          bk7258_dac_get_stats(&snap[phase][0]);
256	          for (int i = 0; i < 32; i++)
257	            {
258	              bk7258_dac_fifo_write(UINT32_C(0x12341234));
259	            }
260	
261	          bk7258_dac_get_stats(&snap[phase][1]);
262	          usleep(5000);
263	          bk7258_dac_get_stats(&snap[phase][2]);
264	          bk7258_dac_stop();
265	        }
266	
267	      bk7258_dac_deinit();
268	
269	      for (int phase = 0; phase < 2; phase++)
270	        {
271	          const struct bk7258_dac_stats_s *cfg = &snap[phase][0];
272	
273	          printf("[bk] FIFOCPU %s ver=%08lx global=%08lx\n",
274	                 clock_name[phase],
275	                 (unsigned long)cfg->version_id,
276	                 (unsigned long)cfg->global_status);
277	          printf("[bk] FIFOCPU %s sys clk1=%08lx clk2=%08lx "
278	                 "dev=%08lx pwr=%08lx spi=%08lx\n",
279	                 clock_name[phase],
280	                 (unsigned long)cfg->sys_clk_div_mode1,
281	                 (unsigned long)cfg->sys_clk_div_mode2,
282	                 (unsigned long)cfg->device_clk_enable,
283	                 (unsigned long)cfg->power_sleep_wakeup,
284	                 (unsigned long)cfg->analog_spi_state);
285	          printf("[bk] FIFOCPU %s mem sd=%08lx ds=%08lx\n",
286	                 clock_name[phase],
287	                 (unsigned long)cfg->device_mem_ctrl1,
288	                 (unsigned long)cfg->device_mem_ctrl2);
289	          printf("[bk] FIFOCPU %s ana 5=%08lx 18=%08lx 19=%08lx "
290	                 "20=%08lx 21=%08lx\n",
291	                 clock_name[phase],
292	                 (unsigned long)cfg->ana_reg5,
293	                 (unsigned long)cfg->ana_reg18,
294	                 (unsigned long)cfg->ana_reg19,
295	                 (unsigned long)cfg->ana_reg20,
296	                 (unsigned long)cfg->ana_reg21);
297	          printf("[bk] FIFOCPU %s apll 25=%08lx 26=%08lx 27=%08lx\n",
298	                 clock_name[phase],
299	                 (unsigned long)cfg->ana_reg25,
300	                 (unsigned long)cfg->ana_reg26,
301	                 (unsigned long)cfg->ana_reg27);
302	
303	          for (int sample = 0; sample < 3; sample++)
304	            {
305	              static const char *const sample_name[] =
306	                {"before", "written", "drained"};
307	              const struct bk7258_dac_stats_s *st = &snap[phase][sample];
308	
309	              printf("[bk] FIFOCPU %s %-7s fifo=%08lx cfg=%08lx "
310	                     "audio=%08lx dac=%08lx ext=%08lx clk=%08lx\n",
311	                     clock_name[phase], sample_name[sample],
312	                     (unsigned long)st->fifo_status,
313	                     (unsigned long)st->fifo_config,
314	                     (unsigned long)st->audio_config,
315	                     (unsigned long)st->dac_config0,
316	                     (unsigned long)st->extend_cfg,
317	                     (unsigned long)st->clk_control);
318	            }
319	        }
320	
321	      fflush(stdout);
322	      ret = 0;
323	      goto cleanup;
324	    }
325	#else
326	  if (g_fifo_cpu_mode)
327	    {
328	      fprintf(stderr, "-F requires CONFIG_AUDIO_BK7258\n");
329	      ret = -ENOSYS;
330	      goto cleanup;
331	    }
332	#endif
333	
334	  ret = ioctl(fd, AUDIOIOC_REGISTERMQ, (unsigned long)mq);
335	  if (ret < 0)
336	    {
337	      fprintf(stderr, "AUDIOIOC_REGISTERMQ failed: %d\n", errno);
338	      goto cleanup;
339	    }
340	  printf("[bk] regmq ok\n"); fflush(stdout);
341	
342	  ret = ioctl(fd, AUDIOIOC_GETBUFFERINFO, (unsigned long)&buf_info);
343	  if (ret < 0)
344	    {
345	      buf_info.buffer_size = 4096;
346	      buf_info.nbuffers    = 4;
347	    }
348	  printf("[bk] bufinfo n=%u sz=%u\n",
349	         (unsigned)buf_info.nbuffers, (unsigned)buf_info.buffer_size);
350	  fflush(stdout);
351	
352	  total_bytes = (size_t)((int64_t)g_sample_rate * g_channels
353	                         * 2 * g_duration_ms / 1000);
354	
355	  /* Prime the driver with N buffers and then keep it topped up until we
356	   * have queued total_bytes worth of samples, tagging the last buffer
357	   * with AUDIO_APB_FINAL so the driver signals COMPLETE.
358	   */
359	
360	  for (int i = 0; i < buf_info.nbuffers; i++)
361	    {
362	      buf_desc.numbytes  = buf_info.buffer_size;
363	      buf_desc.u.pbuffer = &apb;
364	      ret = ioctl(fd, AUDIOIOC_ALLOCBUFFER, (unsigned long)&buf_desc);
365	      if (ret != sizeof(buf_desc) || apb == NULL)
366	        {
367	          fprintf(stderr, "AUDIOIOC_ALLOCBUFFER failed: %d\n", errno);
368	          goto cleanup;
369	        }
370	
371	      size_t chunk = buf_info.buffer_size;
372	      if (bytes_written + chunk >= total_bytes)
373	        {
374	          chunk = total_bytes - bytes_written;
375	          apb->flags |= AUDIO_APB_FINAL;
376	        }
377	
378	      fill_sine((FAR int16_t *)apb->samp, chunk / 2, &phase);
379	      apb->nbytes    = chunk;
380	      apb->curbyte   = 0;
381	      apb->nmaxbytes = buf_info.buffer_size;
382	      bytes_written += chunk;
383	
384	      buf_desc.u.buffer = apb;
385	      ret = ioctl(fd, AUDIOIOC_ENQUEUEBUFFER, (unsigned long)&buf_desc);
386	      if (ret < 0)
387	        {
388	          fprintf(stderr, "AUDIOIOC_ENQUEUEBUFFER failed: %d\n", errno);
389	          goto cleanup;
390	        }
391	      printf("[bk] enq %d\n", i); fflush(stdout);
392	
393	      if (bytes_written >= total_bytes)
394	        {
395	          break;
396	        }
397	    }
398	
399	  ret = ioctl(fd, AUDIOIOC_START, 0);
400	  if (ret < 0)
401	    {
402	      fprintf(stderr, "AUDIOIOC_START failed: %d\n", errno);
403	      goto cleanup;
404	    }
405	  printf("[bk] start ok, waiting for COMPLETE\n"); fflush(stdout);
406	
407	#ifdef CONFIG_AUDIO_BK7258
408	  if (g_trace_mode)
409	    {
410	      /* Sample the DMA + audio-block state every 5 ms, 40 times.  This
411	       * tells us whether:
412	       *  - remain_len is truly frozen or slowly decrementing
413	       *  - fifo_status oscillates (DAC drains + DMA refills) or is static
414	       *  - the GDMA ISR ever fires (isr_count > 0)
415	       */
416	
417	      struct bk7258_gdma_stats_s gs;
418	      struct bk7258_dac_stats_s  ds;
419	
420	      bk7258_gdma_get_stats(&gs);
421	      printf("[bk] TRACE cfg req=%08lx src_loop=%08lx-%08lx\n",
422	             (unsigned long)gs.ch[0].reqmux,
423	             (unsigned long)gs.ch[0].src_loop_start,
424	             (unsigned long)gs.ch[0].src_loop_end);
425	      printf("[bk] TRACE cfg dst_loop=%08lx-%08lx\n",
426	             (unsigned long)gs.ch[0].dst_loop_start,
427	             (unsigned long)gs.ch[0].dst_loop_end);
428	      printf("[bk] TRACE t(ms) remain src_rd dst_wr ctrl prio\n");
429	      printf("[bk] TRACE       fifo_st audio_cfg isr fin err\n");
430	      for (int t = 0; t < 40; t++)
431	        {
432	          bk7258_gdma_get_stats(&gs);
433	          bk7258_dac_get_stats(&ds);
434	          uint32_t remain = gs.ch[0].status & 0x1FFFFu;
435	          printf("  %3d %5lu %08lx %08lx %08lx %08lx\n",
436	                 t * 5,
437	                 (unsigned long)remain,
438	                 (unsigned long)gs.ch[0].src,
439	                 (unsigned long)gs.ch[0].dst,
440	                 (unsigned long)gs.ch[0].ctrl,
441	                 (unsigned long)gs.prio_mode);
442	          printf("      %08lx %08lx %3lu %3lu %3lu\n",
443	                 (unsigned long)ds.fifo_status,
444	                 (unsigned long)ds.audio_config,
445	                 (unsigned long)gs.isr_count,
446	                 (unsigned long)gs.finish_count,
447	                 (unsigned long)gs.buserr_count);
448	          fflush(stdout);
449	          usleep(5000);
450	        }
451	
452	      (void)ioctl(fd, AUDIOIOC_STOP, 0);
453	      goto cleanup;
454	    }
455	#endif
456	
457	  /* Drive the queue until COMPLETE. */
458	
459	  bool done = false;
460	  int timeout_count = 0;
461	  while (!done)
462	    {
463	      struct timespec abs_to;
464	      clock_gettime(CLOCK_REALTIME, &abs_to);
465	      abs_to.tv_sec += 2;
466	      msglen = mq_timedreceive(mq, (FAR char *)&msg, sizeof(msg), &prio,
467	                               &abs_to);
468	      if (msglen < 0 && errno == ETIMEDOUT)
469	        {
470	          timeout_count++;
471	          fprintf(stderr, "[bk] timeout %d, dumping GDMA state\n",
472	                  timeout_count);
473	#ifdef CONFIG_AUDIO_BK7258
474	          {
475	            struct bk7258_gdma_stats_s st;
476	            bk7258_gdma_get_stats(&st);
477	            printf("  isr=%lu fin=%lu half=%lu err=%lu\n",
478	                   (unsigned long)st.isr_count,
479	                   (unsigned long)st.finish_count,
480	                   (unsigned long)st.half_count,
481	                   (unsigned long)st.buserr_count);
482	            printf("  cpu_int_en @0x%08lx = 0x%08lx (bit11 must be 1)\n",
483	                   (unsigned long)st.cpu_int_en_reg,
484	                   (unsigned long)st.cpu_int_en_val);
485	            printf("  dev_clk_en = 0x%08lx (bit16 must be 1)\n",
486	                   (unsigned long)st.dev_clk_en_val);
487	            printf("  prio_mode=0x%08lx int_st0=0x%08lx int_alloc=0x%08lx\n",
488	                   (unsigned long)st.prio_mode,
489	                   (unsigned long)st.int_status0,
490	                   (unsigned long)st.int_allocate);
491	            for (int ci = 0; ci < 8; ci++)
492	              {
493	                if (st.ch[ci].ctrl == 0 && !st.ch[ci].in_use)
494	                  {
