static inline void dma_ll_set_secure_attr(dma_hw_t *hw, dma_id_t id, dma_sec_attr_t attr)
{
	if (attr == DMA_ATTR_NON_SEC) {
		hw->secure_attr.attr &= ~(BIT(id) & 0xFFF);
	} else if (attr == DMA_ATTR_SEC) {
		hw->secure_attr.attr |= (BIT(id) & 0xFFF);
	}
}

