putreg32(0, BK7258_DMA_PRIO_MODE);
putreg32(DMA_PRIO_SOFT_RESET, BK7258_DMA_PRIO_MODE);
up_udelay(10);
putreg32(0, BK7258_DMA_PRIO_MODE);

