#endif

    dma_id_init_common(id);
    DMA_LOGV("%s and %d 0x%x\r\n",__func__,__LINE__,s_dma[dma_num].hal);
    DMA_LOGV("%s and %d %d\r\n",__func__,__LINE__,dma_channel);
    return dma_hal_init_dma(&s_dma[dma_num].hal, dma_channel, config);
}

