182	/* One-shot APLL bring-up (spec §2.2).  cal_val is the family-specific cal
183	 * word; caller decides based on sample rate.
184	 */
185	
186	static int bk7258_apll_program(uint32_t cal_val)
187	{
188	  int ret;
189	
190	  /* Clear the "power-down APLL" bit — active-high in ana_reg5[13]. */
191	
192	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG_APLL_PWD,
193	                           ANA_REG5_PWDAUDPLL_BIT, 0x1u, 0);
194	  if (ret < 0)
195	    {
196	      return ret;
197	    }
198	
199	  ret = bk7258_ana_reg_write(BK7258_ANA_REG26_APLL_CAL, cal_val);
200	  if (ret < 0)
201	    {
202	      return ret;
203	    }
204	
205	  ret = bk7258_ana_reg_write(BK7258_ANA_REG25_APLL_CFG,
206	                             BK7258_APLL_CONFIG_VAL);
207	  if (ret < 0)
208	    {
209	      return ret;
210	    }
211	
212	  /* SPI trigger pulse.  AVDK loops delay(10); we use 200 us as a
213	   * conservative equivalent while APLL locks.
214	   */
215	
216	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG25_APLL_CFG,
217	                           ANA_REG25_SPI_TRIGGER_BIT, 0x1u, 1);
218	  if (ret < 0)
219	    {
220	      return ret;
221	    }
222	
223	  /* AVDK loops delay(10) here (approximately 10 ms on their RTOS tick).
224	   * Waiting only a couple hundred microseconds is not enough for the APLL
225	   * to lock, and the DAC clock silently falls back to a divided XTAL — the
226	   * DAC block appears configured but the FIFO stops draining after a few
227	   * words.  10 ms matches the reference bring-up.
228	   */
229	
230	  up_mdelay(20);
231	
232	  return bk7258_ana_reg_bit(BK7258_ANA_REG25_APLL_CFG,
233	                            ANA_REG25_SPI_TRIGGER_BIT, 0x1u, 0);
234	}
