int bk7258_aud_subsystem_init(void)
{
  irqstate_t flags;
  int ret = OK;

  flags = spin_lock_irqsave(&g_bk7258_aud_lock);
  if (g_bk7258_aud_subsys_ready)
    {
      spin_unlock_irqrestore(&g_bk7258_aud_lock, flags);
      return OK;
