388	int bk7258_dac_configure(const struct bk7258_dac_cfg_s *cfg)
389	{
390	  irqstate_t flags;
391	  uint32_t v;
392	  int ret;
393	
394	  if (cfg == NULL)
395	    {
396	      return -EINVAL;
397	    }
398	
399	  if (!g_bk7258_aud_subsys_ready)
400	    {
401	      ret = bk7258_aud_subsystem_init();
402	      if (ret < 0)
403	        {
404	          return ret;
405	        }
406	    }
407	
408	  g_bk7258_dac_use_apll = cfg->use_apll;
409	
410	  /* §2.2 clock select. */
411	
412	  if (cfg->use_apll)
413	    {
414	      bk7258_sys_reg_bits(SYS_CLK_DIV_MODE1,
415	                          SYS_CLK_DIV_MODE1_CKSEL_AUD_MASK
416	                              << SYS_CLK_DIV_MODE1_CKSEL_AUD_BIT,
417	                          UINT32_C(1) << SYS_CLK_DIV_MODE1_CKSEL_AUD_BIT);
418	
419	      ret = bk7258_apll_program(BK7258_APLL_CAL_VAL_48K);
420	      if (ret < 0)
421	        {
422	          return ret;
423	        }
424	
425	      v = getreg32(BK7258_AUD_AUDIO_CONFIG);
426	      v |= AUD_AUDIO_CFG_APLL_SEL;
427	      putreg32(v, BK7258_AUD_AUDIO_CONFIG);
428	
429	      /* Divide DMIC clock so it does not steal APLL bandwidth. */
430	
431	      bk7258_sys_reg_bits(SYS_CLK_DIV_MODE2,
432	                          UINT32_C(1) << SYS_CLK_DIV_MODE2_DMIC_DIV_BIT,
433	                          UINT32_C(1) << SYS_CLK_DIV_MODE2_DMIC_DIV_BIT);
434	    }
435	  else
436	    {
437	      bk7258_sys_reg_bits(SYS_CLK_DIV_MODE1,
438	                          SYS_CLK_DIV_MODE1_CKSEL_AUD_MASK
439	                              << SYS_CLK_DIV_MODE1_CKSEL_AUD_BIT,
440	                          0u);
441	
442	      v = getreg32(BK7258_AUD_AUDIO_CONFIG);
443	      v &= ~AUD_AUDIO_CFG_APLL_SEL;
444	      putreg32(v, BK7258_AUD_AUDIO_CONFIG);
445	    }
446	
447	  /* §2.3 step 4: DAC analog path power-up.  On BK7258 (SOC_BK7236XX) the
448	   * BK7256-era right-channel/vdd rails are not-supported no-ops in AVDK;
449	   * we only drive the fields that actually map to silicon.
450	   *
451	   *   dac_bias_en  → ana_reg21[enbs]        (not exposed here, latched by
452	   *                                          the ana_reg21 default value)
453	   *   dac_drv_en   → ana_reg20[dacdrven]
454	   *   dac_dcoc_en  → ana_reg20[lendcoc]
455	   *   dac_idac_en  → ana_reg21[enidacl]
456	   *   dacl_en      → ana_reg20[daclen]
457	   *   diffen       → ana_reg20[diffen]
458	   */
459	
460	  /* AVDK aud_dac_driver.c:81..87 explicitly flips these four bits in this
461	   * order.  ana_reg21.enbs (dac bias) is NOT part of the reset default
462	   * value we programmed earlier and MUST be raised now.
463	   */
464	
465	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG21,
466	                           ANA_REG21_ENBS_BIT, 0x1u, 1);
467	  if (ret < 0)
468	    {
469	      return ret;
470	    }
471	
472	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG20,
473	                           ANA_REG20_DACDRVEN_BIT, 0x1u, 1);
474	  if (ret < 0)
475	    {
476	      return ret;
477	    }
478	
479	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG20,
480	                           ANA_REG20_LENDCOC_BIT, 0x1u, 1);
481	  if (ret < 0)
482	    {
483	      return ret;
484	    }
485	
486	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG21,
487	                           ANA_REG21_ENIDACL_BIT, 0x1u, 1);
488	  if (ret < 0)
489	    {
490	      return ret;
491	    }
492	
493	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG20,
494	                           ANA_REG20_DACLEN_BIT, 0x1u, 1);
495	  if (ret < 0)
496	    {
497	      return ret;
498	    }
499	
500	  /* §2.3 step 6: differential vs single-ended. */
501	
502	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG20,
503	                           ANA_REG20_DIFFEN_BIT, 0x1u,
504	                           cfg->work_mode == BK7258_DAC_WORK_DIFFEN
505	                                             ? 1u : 0u);
506	  if (ret < 0)
507	    {
508	      return ret;
509	    }
510	
511	  /* §2.3 step 7: DAC digital path.  Gain, HPF bypass, clk invert. */
512	
513	  flags = spin_lock_irqsave(&g_bk7258_aud_lock);
514	  v = getreg32(BK7258_AUD_DAC_CONFIG0);
515	  v &= ~(AUD_DAC_CFG0_GAIN_MASK | AUD_DAC_CFG0_CLK_INVERT
516	         | AUD_DAC_CFG0_HPF1_BYPASS | AUD_DAC_CFG0_HPF2_BYPASS);
517	  v |= ((uint32_t)(cfg->gain & 0x3Fu) << AUD_DAC_CFG0_GAIN_SHIFT);

