749	void bk7258_dac_deinit(void)
750	{
751	  uint32_t v;
752	
753	  bk7258_dac_stop();
754	  (void)bk7258_dac_mute(true);
755	
756	  /* Reverse the analog power-up sequence.  Keep the ana_reg defaults in
757	   * place so a future bk7258_dac_configure() does not have to re-run the
758	   * whole subsystem init.
759	   */
760	
761	  (void)bk7258_ana_reg_bit(BK7258_ANA_REG20, ANA_REG20_DACLEN_BIT, 0x1u, 0);
762	  (void)bk7258_ana_reg_bit(BK7258_ANA_REG21, ANA_REG21_ENIDACL_BIT, 0x1u, 0);
763	  (void)bk7258_ana_reg_bit(BK7258_ANA_REG20, ANA_REG20_LENDCOC_BIT, 0x1u, 0);
764	  (void)bk7258_ana_reg_bit(BK7258_ANA_REG20, ANA_REG20_DACDRVEN_BIT, 0x1u, 0);
765	
766	  /* Restore the vendor deinit clock baseline: select XTAL in both the SYS
767	   * mux and AUD block, clear the APLL-only DMIC divider, then power APLL
768	   * down.  This makes the next configure independent of the previous one.
769	   */
770	
771	  v = getreg32(BK7258_AUD_AUDIO_CONFIG);
772	  v &= ~AUD_AUDIO_CFG_APLL_SEL;
773	  putreg32(v, BK7258_AUD_AUDIO_CONFIG);
774	  bk7258_sys_reg_bits(SYS_CLK_DIV_MODE1,
775	                      SYS_CLK_DIV_MODE1_CKSEL_AUD_MASK
776	                          << SYS_CLK_DIV_MODE1_CKSEL_AUD_BIT,
777	                      0u);
778	  bk7258_sys_reg_bits(SYS_CLK_DIV_MODE2,
779	                      UINT32_C(1) << SYS_CLK_DIV_MODE2_DMIC_DIV_BIT,
780	                      0u);
781	  (void)bk7258_ana_reg_bit(BK7258_ANA_REG_APLL_PWD,
782	                           ANA_REG5_PWDAUDPLL_BIT, 0x1u, 1u);
783	
784	  g_bk7258_dac_use_apll  = false;
785	  g_bk7258_dac_configured = false;
786	}
