556	int bk7258_dac_set_sample_rate(uint32_t samp_rate)
557	{
558	  uint32_t sr_code;
559	  uint32_t fracmod = 0;
560	  bool     fracmod_manual = false;
561	  bool     apll_44k_family = false;
562	  uint32_t v;
563	  int ret;
564	
565	  switch (samp_rate)
566	    {
567	      case 8000:
568	        sr_code = AUD_SAMP_RATE_8K;
569	        break;
570	
571	      case 16000:
572	        sr_code = AUD_SAMP_RATE_16K;
573	        break;
574	
575	      case 44100:
576	        sr_code = AUD_SAMP_RATE_44_1K;
577	        apll_44k_family = true;
578	        break;
579	
580	      case 48000:
581	        sr_code = AUD_SAMP_RATE_48K;
582	        break;
583	
584	      case 11025:
585	        sr_code = AUD_SAMP_RATE_44_1K;
586	        fracmod = BK7258_AUD_CONST_DIV_44_1K << 2;
587	        fracmod_manual = true;
588	        apll_44k_family = true;
589	        break;
590	
591	      case 22050:
592	        sr_code = AUD_SAMP_RATE_44_1K;
593	        fracmod = BK7258_AUD_CONST_DIV_44_1K << 1;
594	        fracmod_manual = true;
595	        apll_44k_family = true;
596	        break;
597	
598	      case 12000:
599	        sr_code = AUD_SAMP_RATE_48K;
600	        fracmod = BK7258_AUD_CONST_DIV_48K << 2;
601	        fracmod_manual = true;
602	        break;
603	
604	      case 24000:
605	        sr_code = AUD_SAMP_RATE_48K;
606	        fracmod = BK7258_AUD_CONST_DIV_48K << 1;
607	        fracmod_manual = true;
608	        break;
609	
610	      case 32000:
611	        sr_code = AUD_SAMP_RATE_16K;
612	        fracmod = BK7258_AUD_CONST_DIV_16K >> 1;
613	        fracmod_manual = true;
614	        break;
615	
616	      default:
617	        auderr("BK7258: unsupported sample rate %lu\n",
618	               (unsigned long)samp_rate);
619	        return -EINVAL;
620	    }
621	
622	  /* On APLL, the 44.1k family requires a different cal value.  Re-run the
623	   * APLL bring-up transparently.
624	   */
625	
626	  if (g_bk7258_dac_use_apll)
627	    {
628	      ret = bk7258_apll_program(apll_44k_family
629	                                    ? BK7258_APLL_CAL_VAL_44_1K
630	                                    : BK7258_APLL_CAL_VAL_48K);
631	      if (ret < 0)
632	        {
633	          return ret;
634	        }
635	    }
636	
637	  /* Program fracmod first (upper half), then the samp_rate_DAC bits.  This
638	   * mirrors AVDK ordering and avoids a transient rate mismatch on the DAC
639	   * clock.
640	   */
641	
642	  v = getreg32(BK7258_AUD_EXTEND_CFG);
643	  v &= ~AUD_EXT_CFG_DAC_FRACMOD_MAN;
644	  if (fracmod_manual)
645	    {
646	      v |= AUD_EXT_CFG_DAC_FRACMOD_MAN;
647	    }
648	
649	  putreg32(v, BK7258_AUD_EXTEND_CFG);
650	
651	  if (fracmod_manual)
652	    {
653	      putreg32(fracmod, BK7258_AUD_DAC_FRACMOD);
654	    }
655	
656	  v = getreg32(BK7258_AUD_AUDIO_CONFIG);
657	  v &= ~AUD_AUDIO_CFG_SAMP_RATE_MASK;
658	  v |= (sr_code << AUD_AUDIO_CFG_SAMP_RATE_SHIFT)
659	       & AUD_AUDIO_CFG_SAMP_RATE_MASK;
660	  putreg32(v, BK7258_AUD_AUDIO_CONFIG);
661	
662	  return OK;

