380	                          const struct bk7258_dma_m2p_cfg_s *cfg)
381	{
382	  uint32_t ctrl;
383	  uint32_t reqmux;
384	  uint32_t transfer_len;
385	
386	  if (ch < 0 || ch >= BK7258_GDMA_CHANNELS || cfg == NULL)
387	    {
388	      return -EINVAL;
389	    }
390	
391	  if (cfg->buf == 0 || cfg->buf_len == 0 || cfg->dest == 0)
392	    {
393	      return -EINVAL;
394	    }
395	
396	  if (cfg->src_width > BK7258_DMA_WIDTH_32 ||
397	      cfg->dst_width > BK7258_DMA_WIDTH_32)
398	    {
399	      return -EINVAL;
400	    }
401	
402	  /* transfer_len is a byte count encoded as N - 1, independent of the
403	   * source and destination widths.  This matches the vendor DMA LL and
404	   * keeps the hardware remain_len value in bytes as well.
405	   */
406	
407	  if (cfg->buf_len > 0x10000u)
408	    {
409	      return -EINVAL;
410	    }
411	
412	  transfer_len = cfg->buf_len - 1u;
413	
414	  /* Stash the client callback before we start; the ISR reads it. */
415	
416	  g_bk7258_gdma_ch[ch].cb  = cfg->callback;
417	  g_bk7258_gdma_ch[ch].arg = cfg->arg;
418	
419	  /* Reset the channel to a known state: disable, clear pending IRQs. */
420	
421	  putreg32(0, DMA_CH_CTRL(ch));
422	  putreg32(DMA_STAT_FIN_INT | DMA_STAT_HALF_INT | DMA_STAT_BUS_ERR_INT,
423	           DMA_CH_STATUS(ch));
424	
425	  /* Source: circular buffer in memory, address auto-increment. */
426	
427	  putreg32((uint32_t)cfg->buf,                DMA_CH_SRC_ADDR(ch));
428	  if (!cfg->one_shot)
429	    {
430	      putreg32((uint32_t)cfg->buf,            DMA_CH_SRC_LOOP_START(ch));
431	      putreg32((uint32_t)(cfg->buf + cfg->buf_len),
432	               DMA_CH_SRC_LOOP_END(ch));
433	    }
434	  else
435	    {
436	      putreg32(0, DMA_CH_SRC_LOOP_START(ch));
437	      putreg32(0, DMA_CH_SRC_LOOP_END(ch));
438	    }
439	
440	  /* Destination: peripheral FIFO port, no increment, no loop. */
441	
442	  /* Destination: single 32-bit FIFO port.  Even though the physical
443	   * address must never change, the AVDK reference (onboard_speaker_stream.c
444	   * :461-486) sets dst_addr_inc_en=1 and dst_addr_loop_en=1 with
445	   * end = start + 4 so the DMA controller keeps advancing its internal
446	   * pointer and re-asserts the request line after each beat.  With
447	   * inc=0/loop=0 the controller latches the destination once and stops
448	   * requesting new data after only a few words (observed: remain_len
449	   * frozen at 1021, FIFO empty, no bus error).
450	   */
451	
452	  putreg32((uint32_t)cfg->dest,               DMA_CH_DST_ADDR(ch));
453	  putreg32((uint32_t)cfg->dest,               DMA_CH_DST_LOOP_START(ch));
454	  putreg32((uint32_t)cfg->dest + 4u,          DMA_CH_DST_LOOP_END(ch));
455	
456	  /* Request-mux: source from memory, destination to the peripheral.
457	   * bus-error IRQ on so a stray write surfaces immediately.
458	   */
