461	                << DMA_REQ_SRC_MUX_SHIFT;
462	  reqmux |= ((uint32_t)cfg->dest_req_mux & DMA_REQ_MUX_MASK)
463	                << DMA_REQ_DST_MUX_SHIFT;

430	#if 0
