    reg_value &= ~(AUD_CLK_CONTROL_SOFT_RESET_MASK << AUD_CLK_CONTROL_SOFT_RESET_POS);
    reg_value |= ((value & AUD_CLK_CONTROL_SOFT_RESET_MASK) << AUD_CLK_CONTROL_SOFT_RESET_POS);
    REG_WRITE(AUD_CLK_CONTROL_ADDR,reg_value);
}
