521	
522	  /* §2.4: FIFO read threshold.  With threshold=0 the audio block only
523	   * asserts a DMA request when the FIFO is completely empty; on a 32-word
524	   * FIFO that is one request per 32 samples, and combined with any DMA
525	   * arbitration latency the FIFO under-runs and stops requesting.  AVDK
526	   * uses 4 for BK7256; 8 leaves comfortable headroom on BK7258.
527	   */
528	
529	  {
530	    uint32_t fifo_cfg;
531	    fifo_cfg  = getreg32(BK7258_AUD_FIFO_CONFIG);
532	    fifo_cfg &= ~(AUD_FIFO_CFG_DACL_RD_TH_MASK
533	                  | AUD_FIFO_CFG_DACR_RD_TH_MASK);
534	    fifo_cfg |= (UINT32_C(8) << AUD_FIFO_CFG_DACL_RD_TH_SHIFT);
535	    fifo_cfg |= (UINT32_C(8) << AUD_FIFO_CFG_DACR_RD_TH_SHIFT);
536	    putreg32(fifo_cfg, BK7258_AUD_FIFO_CONFIG);
537	  }
538	
539	  /* §2.3 step 8: sample-rate divider. */
540	
541	  ret = bk7258_dac_set_sample_rate(cfg->samp_rate);
542	  if (ret < 0)
543	    {
544	      return ret;
545	    }
546	
547	  /* §2.3 step 9: previously we muted the DAC here.  Empirically the DAC
548	   * FIFO then never fully drains after start() unmutes; leaving the DAC
549	   * un-muted through configure() lets DMA replenish the FIFO immediately.
550	   */
551	
552	  g_bk7258_dac_configured = true;
553	  return OK;
554	}
