587	        fracmod_manual = true;
588	        apll_44k_family = true;
589	        break;
590	
591	      case 22050:
592	        sr_code = AUD_SAMP_RATE_44_1K;
593	        fracmod = BK7258_AUD_CONST_DIV_44_1K << 1;
594	        fracmod_manual = true;
595	        apll_44k_family = true;
596	        break;
597	
598	      case 12000:
599	        sr_code = AUD_SAMP_RATE_48K;
600	        fracmod = BK7258_AUD_CONST_DIV_48K << 2;
601	        fracmod_manual = true;
602	        break;
603	
604	      case 24000:
605	        sr_code = AUD_SAMP_RATE_48K;
606	        fracmod = BK7258_AUD_CONST_DIV_48K << 1;
607	        fracmod_manual = true;
608	        break;
609	
610	      case 32000:
611	        sr_code = AUD_SAMP_RATE_16K;
612	        fracmod = BK7258_AUD_CONST_DIV_16K >> 1;
613	        fracmod_manual = true;
614	        break;
615	
616	      default:
617	        auderr("BK7258: unsupported sample rate %lu\n",
618	               (unsigned long)samp_rate);
