620	    }
621	
622	  /* On APLL, the 44.1k family requires a different cal value.  Re-run the
623	   * APLL bring-up transparently.
624	   */
625	
626	  if (g_bk7258_dac_use_apll)
627	    {
628	      ret = bk7258_apll_program(apll_44k_family
629	                                    ? BK7258_APLL_CAL_VAL_44_1K
630	                                    : BK7258_APLL_CAL_VAL_48K);
