634	        }
635	    }
636	
637	  /* Program fracmod first (upper half), then the samp_rate_DAC bits.  This
638	   * mirrors AVDK ordering and avoids a transient rate mismatch on the DAC
639	   * clock.
640	   */
641	
642	  v = getreg32(BK7258_AUD_EXTEND_CFG);
643	  v &= ~AUD_EXT_CFG_DAC_FRACMOD_MAN;
644	  if (fracmod_manual)
645	    {
646	      v |= AUD_EXT_CFG_DAC_FRACMOD_MAN;
647	    }
648	
649	  putreg32(v, BK7258_AUD_EXTEND_CFG);
650	
651	  if (fracmod_manual)
652	    {
653	      putreg32(fracmod, BK7258_AUD_DAC_FRACMOD);
654	    }
655	
656	  v = getreg32(BK7258_AUD_AUDIO_CONFIG);
657	  v &= ~AUD_AUDIO_CFG_SAMP_RATE_MASK;
658	  v |= (sr_code << AUD_AUDIO_CFG_SAMP_RATE_SHIFT)
659	       & AUD_AUDIO_CFG_SAMP_RATE_MASK;
660	  putreg32(v, BK7258_AUD_AUDIO_CONFIG);
661	
662	  return OK;
663	}
