void bk7258_dac_reset_data_path(void)
{
  irqstate_t flags;

  /* Mirror AVDK's soft-reset pulse: toggle only the self-clearing
   * soft_reset bit.  Never write clk_gate (bit1) — leaving it at its
   * working default (0) is what keeps the DAC/FIFO functional clock
   * alive; asserting bit1 gates the FIFO off and no FPORT write is ever
   * accepted (proven by the FPORT-KICK probe).
   */
  flags = spin_lock_irqsave(&g_bk7258_aud_lock);
  putreg32(getreg32(BK7258_AUD_CLK_CONTROL) | AUD_CLK_CTRL_SOFT_RESET,
           BK7258_AUD_CLK_CONTROL);
  up_udelay(10);
  putreg32(getreg32(BK7258_AUD_CLK_CONTROL) & ~AUD_CLK_CTRL_SOFT_RESET,
           BK7258_AUD_CLK_CONTROL);
  g_bk7258_dac_configured = false;
  spin_unlock_irqrestore(&g_bk7258_aud_lock, flags);
}

